PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE memories (id INTEGER PRIMARY KEY AUTOINCREMENT,created_at INTEGER NOT NULL,kind TEXT NOT NULL DEFAULT 'episodic',content TEXT NOT NULL,importance REAL NOT NULL DEFAULT 0.5,source TEXT NOT NULL DEFAULT 'chat',metadata TEXT NOT NULL DEFAULT '{}');
CREATE TABLE interactions (id INTEGER PRIMARY KEY AUTOINCREMENT,created_at INTEGER NOT NULL,user_text TEXT NOT NULL,assistant_text TEXT NOT NULL,model TEXT NOT NULL,feedback INTEGER,correction TEXT);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_memories_created ON memories(created_at DESC);
CREATE INDEX idx_memories_kind ON memories(kind);
CREATE INDEX idx_interactions_created ON interactions(created_at DESC);
