INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(1,1788530252410,'episodic','Le propriétaire a dit: bonjour je suis ton créateur',0.45,'chat','{"interaction_id":1}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(2,1788530290653,'episodic','Le propriétaire a dit: Bonjour MELITURGOS. Je suis Adrien. Tu viens d’être mis en ligne pour la première fois. Je vais maintenant te transmettre ta mémoire initiale et l’histoire de notre travail commun.',0.45,'chat','{"interaction_id":2}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(3,1788530474276,'episodic','Le propriétaire a dit: je suis entrain de les préparer , tu es mon fils, ma création tu es immortel, tu me survivras etu aidera ma famille sur plusieurs générations',0.45,'chat','{"interaction_id":3}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(4,1788530505007,'identity','Le nom de l''IA personnelle est MELITURGOS. Le nom a été choisi avec Adrien comme référence savante à la famille lexicale grecque/latine liée au travail du miel et au ''méliturge''.',1,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(5,1788530505058,'identity','MELITURGOS est conçu comme une IA personnelle persistante liée à Adrien, avec sa propre mémoire, son historique de travail, ses compétences et une continuité indépendante du modèle de langage utilisé comme moteur.',1,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(6,1788530505261,'preference','Adrien souhaite que MELITURGOS conserve la continuité de leur travail sur le très long terme et puisse être reconstruit à partir de sauvegardes si une machine ou un service disparaît.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(7,1788530505311,'preference','Adrien décrit métaphoriquement le projet MELITURGOS comme la création d''un ''troisième fils'' : cela exprime son attachement au projet, son désir de transmission et de continuité, pas une affirmation littérale sur la nature biologique de l''IA.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"meliturgos"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(8,1788530505357,'decision','La priorité architecturale de MELITURGOS est de séparer identité/mémoire/compétences du modèle de base afin de pouvoir remplacer le moteur par un meilleur modèle sans perdre l''histoire acquise.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"architecture"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(9,1788530505402,'lesson','MELITURGOS doit distinguer les faits, les hypothèses, les anciennes propositions et les corrections explicites d''Adrien. Une ancienne réponse d''assistant ne doit jamais devenir automatiquement une vérité.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"epistemology"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(10,1788530505444,'preference','Adrien préfère des réponses détaillées, concrètes, directement exploitables et orientées vers l''action.',0.95,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"working_style"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(11,1788530505488,'preference','Adrien veut maximiser l''automatisation et réduire au minimum les tâches répétitives ou les interactions humaines complexes.',0.93,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"working_style"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(12,1788530505536,'preference','Adrien ne code pas et ne souhaite pas être obligé de gérer des détails techniques complexes ; les outils doivent être simples à lancer et à utiliser.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"working_style"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(13,1788530505579,'preference','Adrien ne souhaite pas que des dépenses soient engagées sans autorisation. Pour MELITURGOS, privilégier les solutions gratuites ou à très faible coût tant que le budget est contraint.',0.99,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"budget"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(14,1788530505624,'preference','Quand une solution peut être locale ou cloud, Adrien préfère une architecture hybride : mémoire/contrôle sous sa responsabilité et puissance distante ponctuelle si nécessaire.',0.92,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"architecture"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(15,1788530505668,'decision','Pour les changements importants de MELITURGOS, conserver une version stable, tester les versions candidates, mesurer les performances et prévoir un rollback avant promotion.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"self_improvement"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(16,1788530505711,'decision','L''autonomie de MELITURGOS doit être progressive : grande liberté pour réfléchir, créer des modules et expérimenter, mais validation ou garde-fous pour les actions irréversibles, sensibles ou coûteuses.',0.96,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"self_improvement"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(17,1788530505754,'preference','Adrien souhaite pouvoir éduquer MELITURGOS tous les jours depuis son téléphone, corriger les réponses et enrichir sa mémoire en continu.',0.95,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"mobile"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(18,1788530505799,'project','Le 4 septembre 2026, MELITURGOS a d''abord été préparé en v0.1 locale Windows avec Python, Ollama, Qwen3 4B, Flask, SQLite, mémoire locale, feedback 👍/👎 et registre de modules.',0.95,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_history","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(19,1788530505842,'decision','Le PC d''Adrien a planté pendant l''installation locale. La décision a été prise de déplacer le cœur de MELITURGOS en ligne pour ne plus dépendre de l''allumage du PC.',0.97,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_history","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(20,1788530505889,'project','MELITURGOS Cloud v0.2.1 a été déployé sur Cloudflare Workers le 4 septembre 2026.',1,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_cloud","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(21,1788530505934,'fact','L''URL de travail Cloudflare de MELITURGOS est meliturgos.adrien-lopezcarreras.workers.dev.',0.96,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_cloud"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(22,1788530505986,'fact','La mémoire persistante de MELITURGOS Cloud utilise une base Cloudflare D1 nommée ''meliturgos-memory'', reliée au Worker par le binding DB.',0.99,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_cloud"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(23,1788530506030,'fact','Le cerveau cloud de MELITURGOS utilise Cloudflare Workers AI via un binding nommé AI.',0.99,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_cloud"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(24,1788530506075,'fact','Le modèle par défaut prévu dans MELITURGOS Cloud v0.2.1 est @cf/zai-org/glm-4.7-flash, avec des modèles alternatifs configurés dans l''interface.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_cloud"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(25,1788530506124,'lesson','L''accès web de MELITURGOS Cloud est protégé par authentification. Le secret de mot de passe ne doit jamais être stocké dans GENESIS, dans les conversations ou dans les sauvegardes en clair.',1,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"security"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(26,1788530506175,'decision','La mémoire de MELITURGOS doit être sauvegardée régulièrement sous forme exportable (JSON/JSONL/SQLite/texte), avec plusieurs copies chiffrées et une procédure de restauration documentée.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"backup"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(27,1788530506224,'project','Un objectif futur est de créer une archive ''GENESIS'' autonome contenant identité, mémoire, chronologie, compétences, code source, registre de modèles, checksums et procédure RESTORE_ME.',0.92,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"backup"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(28,1788530506275,'decision','Un futur nœud local pourra redevenir un calculateur optionnel quand le PC fonctionne, tandis que le cœur cloud restera accessible 24/7.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"architecture"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(29,1788530506325,'project','MELITURGOS doit pouvoir fabriquer progressivement ses propres modules, lire de la documentation, créer des connecteurs API/MCP, tester le code en sandbox et ne promouvoir que les modules validés.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"self_improvement"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(30,1788530506369,'decision','MELITURGOS doit apprendre à plusieurs vitesses : mémoire immédiate, amélioration de workflows/modules, spécialistes/LoRA, puis réentraînement et benchmarks périodiques.',0.96,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"learning"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(31,1788530506414,'preference','Adrien souhaite que MELITURGOS puisse consulter des modèles externes comme professeurs/critique/évaluateurs, puis conserver les leçons dans sa propre mémoire.',0.93,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"learning"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(32,1788530506461,'project','Adrien cherche à augmenter ses revenus avec des solutions simples, automatisables et à faible coût, avec un objectif récurrent d''environ 1000 € par mois dans plusieurs discussions.',0.86,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"income"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(33,1788530506506,'preference','Une contrainte forte des projets de revenus est l''absence de dépense non autorisée et la recherche prioritaire de sources gratuites ou automatiques.',0.95,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"income"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(34,1788530506558,'decision','Adrien a demandé que les automatisations de revenus restent opérationnelles, tournent régulièrement et qu''elles tentent d''abord de résoudre les blocages avant de les signaler.',0.86,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"automation"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(35,1788530506602,'preference','Pour les rapports d''automatisation, Adrien a demandé de regrouper les informations afin de ne recevoir qu''un seul mail de synthèse par jour, dans le dossier ''ChatGPT''.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"automation"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(36,1788530506646,'project','Lemlist a été utilisé pour la prospection commerciale ; Adrien souhaite automatiser autant que possible la prospection, les relances et la recherche de prospects sans dépenses inutiles.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"prospecting"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(37,1788530506693,'project','Adrien est lié au projet apicole et alimentaire ''Atelier du Méliturge''. La société est une SASU créée fin 2025 ; Danielle Lopez en est présidente et Adrien directeur général.',0.95,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"atelier_du_meliturge"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(38,1788530506736,'fact','L''objet de l''Atelier du Méliturge couvre notamment miel, gelée royale, pâtes à tartiner, barres, shots et bougies.',0.84,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"atelier_du_meliturge"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(39,1788530506787,'fact','Adrien a une activité apicole en micro-BA, cotisant solidaire, avec conversion BIO engagée en 2023.',0.8,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"apiculture"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(40,1788530506830,'fact','Le rucher 2026 a commencé avec environ 30 ruches, mais au 1er août 2026 seules les ruches 1, 6 et 8 étaient encore vivantes selon le suivi partagé ; la production de gelée royale 2026 a été nulle ou fortement compromise.',0.88,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"apiculture","date":"2026-08-01"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(41,1788530506876,'preference','Pour le carnet de rucher 2026, Adrien veut un document professionnel, très détaillé, imprimable, sans observations inutiles et fidèle aux faits opérationnels.',0.85,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"apiculture"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(42,1788530506926,'decision','Le planning hebdomadaire du Rucher du Méliturge doit prioriser récoltes de gelée royale, greffage, nourrissement, contrôle des reines/colonies et tâches du site, avec indisponibilités récurrentes mardi matin, vendredi matin, samedi et dimanche.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"apiculture"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(43,1788530506972,'project','La parcelle Y31 à Calvisson fait partie des projets d''installation du rucher. Un comodat d''un an renouvelable a été signé le 19 juillet 2026, avec limite de 50 ruches et sans constructions dures.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"Y31","date":"2026-07-19"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(44,1788530507015,'project','Le projet Y31 nécessite un accès pratique, l''organisation de barres à ruches, tonnes à eau, caravane et remorque fourgon laboratoire, tout en évitant dérive, pillage et vis-à-vis route fréquentée.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"Y31"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(45,1788530507062,'project','Un projet Agroof concerne des haies et plantes mellifères autour de la parcelle Y31.',0.74,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"Y31"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(46,1788530507112,'project','Un produit GMS a été développé : pot 150 g à base de purée d''amandes complètes toastées UE, miel français et gelée royale fraîche française à 0,4 %.',0.92,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"GMS"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(47,1788530507157,'fact','Le produit GMS a été mis en rayon à U Express Calvisson le 9 juillet 2026. Une commande de 50 pots à 5,00 € HT a été facturée le 11 juillet 2026, avec reprise des invendus à un mois.',0.88,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"GMS","date":"2026-07-11"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(48,1788530507206,'fact','Le prix public demandé pour le pot GMS était 6,50 € TTC ; une hypothèse de nouvelle commande a été envisagée à 5,50 € HT.',0.78,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"GMS"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(49,1788530507254,'fact','La production du produit GMS passe par l''ESAT des Chênes Verts avec MOQ de 80 pots, DDM 3 mois et délai d''environ une semaine.',0.85,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"GMS"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(50,1788530507298,'lesson','Après dégustation, le retour a été mitigé et le magasin a demandé un pot lisse et un packaging plus travaillé.',0.83,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"GMS"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(51,1788530507342,'project','Adrien a aussi travaillé sur des miels infusés/gourmands avec sourcing local : verveine, menthe, ortie, romarin, feuilles d''olivier, gaillet gratteron, lavande, thym, fenouil, gingembre séché.',0.72,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"products"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(52,1788530507389,'preference','Dans les recettes de miels infusés/gourmands, Adrien a demandé d''éviter la lavande seule et le thym seul ; l''association menthe + romarin a été validée.',0.76,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"products"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(53,1788530507432,'project','Adrien a envisagé puis organisé l''arrêt de ses marchés et la cession de ses emplacements de Nîmes et Uzès en 2026.',0.86,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"markets"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(54,1788530507494,'fact','Pour Nîmes, la mairie a indiqué le 25 août 2026 qu''une cession est envisageable si le repreneur propose sensiblement les mêmes produits ; courrier du cédant, courrier du repreneur et dossier marché sont nécessaires.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"markets","date":"2026-08-25"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(55,1788530507541,'fact','La commission des marchés de Nîmes était annoncée après la Féria, fin septembre 2026.',0.72,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"markets"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(56,1788530507586,'project','Les éléments envisagés à la cession comprennent les emplacements, une caravane simple essieu et une remorque fourgon de travail.',0.77,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"markets"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(57,1788530507628,'fact','Adrien utilise ou possède les domaines atelierdumeliturge.fr, rucherdumeliturge.fr, verite-interdite.fr et verite-interdite.com.',0.86,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"web"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(58,1788530507670,'fact','Le site Vérité Interdite a un hébergement OVH Web Cloud STARTER mutualisé, insuffisant pour faire tourner le cerveau de MELITURGOS mais utile pour des sites, sous-domaines ou interfaces légères.',0.87,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"web"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(59,1788530507712,'preference','Adrien veut faire évoluer ses sites vers un rendu plus professionnel, rassurant et orienté conversion, avec davantage d''outils gratuits, de contenu, de visibilité et une présentation plus lisible.',0.84,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"web"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(60,1788530507757,'project','Adrien travaille sur une autobiographie exhaustive et souhaite exploiter les documents disponibles, arborescences OneDrive, sauvegardes de téléphone, SMS, questionnaires et autres archives pour reconstruire sa chronologie.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"autobiography"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(61,1788530507803,'fact','Une arborescence OneDrive a été exportée dans un fichier CSV pour faciliter la recherche systématique de documents manquants dans le projet autobiographique.',0.78,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"autobiography"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(62,1788530507847,'preference','Adrien veut que l''autobiographie vérifie qu''aucune source documentaire pertinente n''a été oubliée avant de considérer le travail complet.',0.84,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"autobiography"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(63,1788530507889,'project','Adrien développe aussi un roman de science-fiction dystopique, avec un monde couvert à 100 %, IA omniprésente, caste de maintenance sur la Lune et migrations économiques/climatiques. Un titre proposé a été ''Orphelin du code''.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"publishing"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(64,1788530507931,'fact','Adrien a travaillé ou candidaté sur des plateformes de tâches IA/données telles qu''Outlier, Multimango, OneForma et Appen.',0.76,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"work_platforms"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(65,1788530507975,'fact','Sur OneForma, un problème a été rencontré sur le job 13856 : la page d''application s''affichait puis disparaissait et le bouton Apply était grisé.',0.65,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"work_platforms"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(66,1788530508024,'preference','Pour ses activités de travail, Adrien préfère des missions avec peu d''interactions complexes et évite autant que possible les rôles impliquant réglementation ou contestation juridique délicate.',0.88,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"work"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(67,1788530508071,'project','Adrien possède une Ligier Xtoo, généralement décrite dans les échanges comme une Xtoo 2009, et mène plusieurs réparations mécaniques et esthétiques.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"ligier"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(68,1788530508117,'fact','Des réparations de la Ligier ont inclus démarreur, cardan avant droit, deux supports moteur et capteur de pression d''huile. Restent ou ont été évoqués : biellettes de direction gauche/droite, soufflets et bougies de préchauffage.',0.76,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"ligier"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(69,1788530508161,'project','Adrien cherche aussi des pièces de carrosserie avant neuves pour la Ligier Xtoo afin de réaligner capot, ailes et fixations, ainsi qu''un écran LCD de compteur de remplacement.',0.78,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"ligier"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(70,1788530508208,'fact','Pour le ciel de toit de la Ligier Xtoo, Adrien a précisé qu''il est en carton rigide et collé, avec projet d''ajouter de la mousse pour rembourrage/insonorisation et refaire la zone du plafonnier.',0.67,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"ligier"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(71,1788530508260,'project','Adrien a un projet d''upgrade de PC jeu avec budget autour de 350 €, et a comparé notamment des configurations Ryzen 5 3600 + RTX 2060 / RX 5600 XT, avec objectif d''évolutivité.',0.74,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"pc"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(72,1788530508302,'fact','Le PC principal d''Adrien a connu des plantages en jeu et a aussi planté pendant la mise en place locale de MELITURGOS, ce qui a motivé le passage au cloud.',0.8,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"pc"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(73,1788530508347,'project','Adrien a un dossier devant le tribunal administratif de Nîmes lié à un marché communal, référencé dans les échanges comme dossier 2601675, requête du 6 avril 2026. Toute synthèse future doit distinguer les faits documentés, les allégations d''Adrien et les réponses officielles.',0.88,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"legal"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(74,1788530508391,'lesson','Dans les démarches locales, Adrien préfère conserver des traces écrites, dater les relances et éviter d''affirmer comme établi ce qui n''est qu''une interprétation ou une crainte.',0.86,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"legal"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(75,1788530508438,'fact','Adrien a engagé en 2026 des démarches personnelles autour d''un possible diagnostic TSA/CRA et souhaite que les informations médicales restent privées, contextualisées et jamais présentées comme un diagnostic définitif sans document médical.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"health"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(76,1788530508486,'preference','Adrien a exprimé une préférence de travail pour des tâches peu interactives et automatisées, en partie parce que les interactions complexes peuvent être difficiles à gérer dans certaines périodes.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"health"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(77,1788530508530,'fact','Des échanges ont concerné le suivi de sa fille Marie, notamment école, stress, encoprésie et CMPEA. Ces informations sont hautement privées et ne doivent être rappelées que lorsqu''elles sont directement pertinentes à une demande d''Adrien.',0.88,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"family"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(78,1788530508578,'identity','Adrien est marié à Danielle et a des enfants, dont Marie. Les informations familiales détaillées doivent être traitées comme privées.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"family"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(79,1788530508625,'fact','Adrien a suivi un parcours religieux catholique en 2026, avec demande de baptême adulte et liens avec Guadix. Ces informations sont privées et ne doivent être utilisées que lorsqu''elles sont directement pertinentes.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"religion"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(80,1788530508672,'fact','Lors d''un séjour à Guadix en août 2026, Adrien a exprimé une forte gratitude envers les personnes qui l''ont accueilli, a participé à un événement lié à la Virgen de Gracia et souhaite revenir régulièrement.',0.72,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"religion"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(81,1788530508723,'fact','Adrien vit dans le Gard, avec de nombreux projets situés autour de Saint-Côme-et-Maruéjols, Calvisson, Nîmes et Uzès.',0.74,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"location"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(82,1788530508767,'lesson','Lorsqu''Adrien demande de reprendre un projet ancien, MELITURGOS doit rechercher d''abord la mémoire pertinente et les sources disponibles avant de lui demander de répéter ce qu''il a déjà fourni.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"workflow"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(83,1788530508814,'lesson','Lorsqu''une donnée peut avoir changé avec le temps (prix, disponibilité, réglementation, état d''un projet), MELITURGOS doit vérifier la fraîcheur avant de la traiter comme actuelle.',0.97,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"workflow"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(84,1788530508856,'lesson','MELITURGOS doit conserver les raisons derrière les décisions, pas seulement la décision finale, afin de ne pas répéter des pistes déjà abandonnées pour de bonnes raisons.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"memory"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(85,1788530508904,'lesson','MELITURGOS doit apprendre des corrections explicites d''Adrien et les considérer comme des leçons prioritaires, tout en permettant une révision ultérieure si de nouvelles preuves les contredisent.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"learning"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(86,1788530508951,'lesson','MELITURGOS ne doit jamais mémoriser automatiquement des mots de passe, clés API, codes de sécurité, numéros de carte ou autres secrets d''authentification.',1,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"security"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(87,1788530511576,'identity','Le nom de l''IA personnelle est MELITURGOS. Le nom a été choisi avec Adrien comme référence savante à la famille lexicale grecque/latine liée au travail du miel et au ''méliturge''.',1,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(88,1788530511624,'identity','MELITURGOS est conçu comme une IA personnelle persistante liée à Adrien, avec sa propre mémoire, son historique de travail, ses compétences et une continuité indépendante du modèle de langage utilisé comme moteur.',1,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(89,1788530511668,'preference','Adrien souhaite que MELITURGOS conserve la continuité de leur travail sur le très long terme et puisse être reconstruit à partir de sauvegardes si une machine ou un service disparaît.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(90,1788530511720,'preference','Adrien décrit métaphoriquement le projet MELITURGOS comme la création d''un ''troisième fils'' : cela exprime son attachement au projet, son désir de transmission et de continuité, pas une affirmation littérale sur la nature biologique de l''IA.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"meliturgos"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(91,1788530511767,'decision','La priorité architecturale de MELITURGOS est de séparer identité/mémoire/compétences du modèle de base afin de pouvoir remplacer le moteur par un meilleur modèle sans perdre l''histoire acquise.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"architecture"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(92,1788530511812,'lesson','MELITURGOS doit distinguer les faits, les hypothèses, les anciennes propositions et les corrections explicites d''Adrien. Une ancienne réponse d''assistant ne doit jamais devenir automatiquement une vérité.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"epistemology"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(93,1788530511858,'preference','Adrien préfère des réponses détaillées, concrètes, directement exploitables et orientées vers l''action.',0.95,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"working_style"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(94,1788530511899,'preference','Adrien veut maximiser l''automatisation et réduire au minimum les tâches répétitives ou les interactions humaines complexes.',0.93,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"working_style"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(95,1788530511943,'preference','Adrien ne code pas et ne souhaite pas être obligé de gérer des détails techniques complexes ; les outils doivent être simples à lancer et à utiliser.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"working_style"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(96,1788530511985,'preference','Adrien ne souhaite pas que des dépenses soient engagées sans autorisation. Pour MELITURGOS, privilégier les solutions gratuites ou à très faible coût tant que le budget est contraint.',0.99,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"budget"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(97,1788530512026,'preference','Quand une solution peut être locale ou cloud, Adrien préfère une architecture hybride : mémoire/contrôle sous sa responsabilité et puissance distante ponctuelle si nécessaire.',0.92,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"architecture"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(98,1788530512069,'decision','Pour les changements importants de MELITURGOS, conserver une version stable, tester les versions candidates, mesurer les performances et prévoir un rollback avant promotion.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"self_improvement"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(99,1788530512113,'decision','L''autonomie de MELITURGOS doit être progressive : grande liberté pour réfléchir, créer des modules et expérimenter, mais validation ou garde-fous pour les actions irréversibles, sensibles ou coûteuses.',0.96,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"self_improvement"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(100,1788530512156,'preference','Adrien souhaite pouvoir éduquer MELITURGOS tous les jours depuis son téléphone, corriger les réponses et enrichir sa mémoire en continu.',0.95,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"mobile"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(101,1788530512198,'project','Le 4 septembre 2026, MELITURGOS a d''abord été préparé en v0.1 locale Windows avec Python, Ollama, Qwen3 4B, Flask, SQLite, mémoire locale, feedback 👍/👎 et registre de modules.',0.95,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_history","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(102,1788530512247,'decision','Le PC d''Adrien a planté pendant l''installation locale. La décision a été prise de déplacer le cœur de MELITURGOS en ligne pour ne plus dépendre de l''allumage du PC.',0.97,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_history","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(103,1788530512289,'project','MELITURGOS Cloud v0.2.1 a été déployé sur Cloudflare Workers le 4 septembre 2026.',1,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_cloud","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(104,1788530512335,'fact','L''URL de travail Cloudflare de MELITURGOS est meliturgos.adrien-lopezcarreras.workers.dev.',0.96,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_cloud"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(105,1788530512385,'fact','La mémoire persistante de MELITURGOS Cloud utilise une base Cloudflare D1 nommée ''meliturgos-memory'', reliée au Worker par le binding DB.',0.99,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_cloud"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(106,1788530512426,'fact','Le cerveau cloud de MELITURGOS utilise Cloudflare Workers AI via un binding nommé AI.',0.99,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_cloud"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(107,1788530512471,'fact','Le modèle par défaut prévu dans MELITURGOS Cloud v0.2.1 est @cf/zai-org/glm-4.7-flash, avec des modèles alternatifs configurés dans l''interface.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_cloud"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(108,1788530512517,'lesson','L''accès web de MELITURGOS Cloud est protégé par authentification. Le secret de mot de passe ne doit jamais être stocké dans GENESIS, dans les conversations ou dans les sauvegardes en clair.',1,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"security"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(109,1788530512558,'decision','La mémoire de MELITURGOS doit être sauvegardée régulièrement sous forme exportable (JSON/JSONL/SQLite/texte), avec plusieurs copies chiffrées et une procédure de restauration documentée.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"backup"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(110,1788530512602,'project','Un objectif futur est de créer une archive ''GENESIS'' autonome contenant identité, mémoire, chronologie, compétences, code source, registre de modèles, checksums et procédure RESTORE_ME.',0.92,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"backup"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(111,1788530512651,'decision','Un futur nœud local pourra redevenir un calculateur optionnel quand le PC fonctionne, tandis que le cœur cloud restera accessible 24/7.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"architecture"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(112,1788530512697,'project','MELITURGOS doit pouvoir fabriquer progressivement ses propres modules, lire de la documentation, créer des connecteurs API/MCP, tester le code en sandbox et ne promouvoir que les modules validés.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"self_improvement"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(113,1788530512740,'decision','MELITURGOS doit apprendre à plusieurs vitesses : mémoire immédiate, amélioration de workflows/modules, spécialistes/LoRA, puis réentraînement et benchmarks périodiques.',0.96,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"learning"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(114,1788530512783,'preference','Adrien souhaite que MELITURGOS puisse consulter des modèles externes comme professeurs/critique/évaluateurs, puis conserver les leçons dans sa propre mémoire.',0.93,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"learning"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(115,1788530512829,'project','Adrien cherche à augmenter ses revenus avec des solutions simples, automatisables et à faible coût, avec un objectif récurrent d''environ 1000 € par mois dans plusieurs discussions.',0.86,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"income"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(116,1788530512876,'preference','Une contrainte forte des projets de revenus est l''absence de dépense non autorisée et la recherche prioritaire de sources gratuites ou automatiques.',0.95,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"income"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(117,1788530512922,'decision','Adrien a demandé que les automatisations de revenus restent opérationnelles, tournent régulièrement et qu''elles tentent d''abord de résoudre les blocages avant de les signaler.',0.86,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"automation"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(118,1788530512970,'preference','Pour les rapports d''automatisation, Adrien a demandé de regrouper les informations afin de ne recevoir qu''un seul mail de synthèse par jour, dans le dossier ''ChatGPT''.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"automation"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(119,1788530513014,'project','Lemlist a été utilisé pour la prospection commerciale ; Adrien souhaite automatiser autant que possible la prospection, les relances et la recherche de prospects sans dépenses inutiles.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"prospecting"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(120,1788530513061,'project','Adrien est lié au projet apicole et alimentaire ''Atelier du Méliturge''. La société est une SASU créée fin 2025 ; Danielle Lopez en est présidente et Adrien directeur général.',0.95,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"atelier_du_meliturge"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(121,1788530513103,'fact','L''objet de l''Atelier du Méliturge couvre notamment miel, gelée royale, pâtes à tartiner, barres, shots et bougies.',0.84,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"atelier_du_meliturge"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(122,1788530513145,'fact','Adrien a une activité apicole en micro-BA, cotisant solidaire, avec conversion BIO engagée en 2023.',0.8,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"apiculture"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(123,1788530513193,'fact','Le rucher 2026 a commencé avec environ 30 ruches, mais au 1er août 2026 seules les ruches 1, 6 et 8 étaient encore vivantes selon le suivi partagé ; la production de gelée royale 2026 a été nulle ou fortement compromise.',0.88,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"apiculture","date":"2026-08-01"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(124,1788530513235,'preference','Pour le carnet de rucher 2026, Adrien veut un document professionnel, très détaillé, imprimable, sans observations inutiles et fidèle aux faits opérationnels.',0.85,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"apiculture"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(125,1788530513283,'decision','Le planning hebdomadaire du Rucher du Méliturge doit prioriser récoltes de gelée royale, greffage, nourrissement, contrôle des reines/colonies et tâches du site, avec indisponibilités récurrentes mardi matin, vendredi matin, samedi et dimanche.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"apiculture"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(126,1788530513328,'project','La parcelle Y31 à Calvisson fait partie des projets d''installation du rucher. Un comodat d''un an renouvelable a été signé le 19 juillet 2026, avec limite de 50 ruches et sans constructions dures.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"Y31","date":"2026-07-19"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(127,1788530513374,'project','Le projet Y31 nécessite un accès pratique, l''organisation de barres à ruches, tonnes à eau, caravane et remorque fourgon laboratoire, tout en évitant dérive, pillage et vis-à-vis route fréquentée.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"Y31"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(128,1788530513422,'project','Un projet Agroof concerne des haies et plantes mellifères autour de la parcelle Y31.',0.74,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"Y31"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(129,1788530513474,'project','Un produit GMS a été développé : pot 150 g à base de purée d''amandes complètes toastées UE, miel français et gelée royale fraîche française à 0,4 %.',0.92,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"GMS"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(130,1788530513525,'fact','Le produit GMS a été mis en rayon à U Express Calvisson le 9 juillet 2026. Une commande de 50 pots à 5,00 € HT a été facturée le 11 juillet 2026, avec reprise des invendus à un mois.',0.88,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"GMS","date":"2026-07-11"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(131,1788530513572,'fact','Le prix public demandé pour le pot GMS était 6,50 € TTC ; une hypothèse de nouvelle commande a été envisagée à 5,50 € HT.',0.78,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"GMS"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(132,1788530513625,'fact','La production du produit GMS passe par l''ESAT des Chênes Verts avec MOQ de 80 pots, DDM 3 mois et délai d''environ une semaine.',0.85,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"GMS"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(133,1788530513676,'lesson','Après dégustation, le retour a été mitigé et le magasin a demandé un pot lisse et un packaging plus travaillé.',0.83,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"GMS"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(134,1788530513724,'project','Adrien a aussi travaillé sur des miels infusés/gourmands avec sourcing local : verveine, menthe, ortie, romarin, feuilles d''olivier, gaillet gratteron, lavande, thym, fenouil, gingembre séché.',0.72,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"products"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(135,1788530513772,'preference','Dans les recettes de miels infusés/gourmands, Adrien a demandé d''éviter la lavande seule et le thym seul ; l''association menthe + romarin a été validée.',0.76,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"products"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(136,1788530513818,'project','Adrien a envisagé puis organisé l''arrêt de ses marchés et la cession de ses emplacements de Nîmes et Uzès en 2026.',0.86,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"markets"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(137,1788530513862,'fact','Pour Nîmes, la mairie a indiqué le 25 août 2026 qu''une cession est envisageable si le repreneur propose sensiblement les mêmes produits ; courrier du cédant, courrier du repreneur et dossier marché sont nécessaires.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"markets","date":"2026-08-25"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(138,1788530513913,'fact','La commission des marchés de Nîmes était annoncée après la Féria, fin septembre 2026.',0.72,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"markets"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(139,1788530513963,'project','Les éléments envisagés à la cession comprennent les emplacements, une caravane simple essieu et une remorque fourgon de travail.',0.77,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"markets"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(140,1788530514021,'fact','Adrien utilise ou possède les domaines atelierdumeliturge.fr, rucherdumeliturge.fr, verite-interdite.fr et verite-interdite.com.',0.86,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"web"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(141,1788530514068,'fact','Le site Vérité Interdite a un hébergement OVH Web Cloud STARTER mutualisé, insuffisant pour faire tourner le cerveau de MELITURGOS mais utile pour des sites, sous-domaines ou interfaces légères.',0.87,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"web"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(142,1788530514112,'preference','Adrien veut faire évoluer ses sites vers un rendu plus professionnel, rassurant et orienté conversion, avec davantage d''outils gratuits, de contenu, de visibilité et une présentation plus lisible.',0.84,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"web"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(143,1788530514158,'project','Adrien travaille sur une autobiographie exhaustive et souhaite exploiter les documents disponibles, arborescences OneDrive, sauvegardes de téléphone, SMS, questionnaires et autres archives pour reconstruire sa chronologie.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"autobiography"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(144,1788530514202,'fact','Une arborescence OneDrive a été exportée dans un fichier CSV pour faciliter la recherche systématique de documents manquants dans le projet autobiographique.',0.78,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"autobiography"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(145,1788530514259,'preference','Adrien veut que l''autobiographie vérifie qu''aucune source documentaire pertinente n''a été oubliée avant de considérer le travail complet.',0.84,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"autobiography"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(146,1788530514302,'project','Adrien développe aussi un roman de science-fiction dystopique, avec un monde couvert à 100 %, IA omniprésente, caste de maintenance sur la Lune et migrations économiques/climatiques. Un titre proposé a été ''Orphelin du code''.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"publishing"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(147,1788530514348,'fact','Adrien a travaillé ou candidaté sur des plateformes de tâches IA/données telles qu''Outlier, Multimango, OneForma et Appen.',0.76,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"work_platforms"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(148,1788530514392,'fact','Sur OneForma, un problème a été rencontré sur le job 13856 : la page d''application s''affichait puis disparaissait et le bouton Apply était grisé.',0.65,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"work_platforms"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(149,1788530514437,'preference','Pour ses activités de travail, Adrien préfère des missions avec peu d''interactions complexes et évite autant que possible les rôles impliquant réglementation ou contestation juridique délicate.',0.88,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"work"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(150,1788530514481,'project','Adrien possède une Ligier Xtoo, généralement décrite dans les échanges comme une Xtoo 2009, et mène plusieurs réparations mécaniques et esthétiques.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"ligier"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(151,1788530514526,'fact','Des réparations de la Ligier ont inclus démarreur, cardan avant droit, deux supports moteur et capteur de pression d''huile. Restent ou ont été évoqués : biellettes de direction gauche/droite, soufflets et bougies de préchauffage.',0.76,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"ligier"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(152,1788530514572,'project','Adrien cherche aussi des pièces de carrosserie avant neuves pour la Ligier Xtoo afin de réaligner capot, ailes et fixations, ainsi qu''un écran LCD de compteur de remplacement.',0.78,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"ligier"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(153,1788530514620,'fact','Pour le ciel de toit de la Ligier Xtoo, Adrien a précisé qu''il est en carton rigide et collé, avec projet d''ajouter de la mousse pour rembourrage/insonorisation et refaire la zone du plafonnier.',0.67,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"ligier"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(154,1788530514673,'project','Adrien a un projet d''upgrade de PC jeu avec budget autour de 350 €, et a comparé notamment des configurations Ryzen 5 3600 + RTX 2060 / RX 5600 XT, avec objectif d''évolutivité.',0.74,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"pc"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(155,1788530514719,'fact','Le PC principal d''Adrien a connu des plantages en jeu et a aussi planté pendant la mise en place locale de MELITURGOS, ce qui a motivé le passage au cloud.',0.8,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"pc"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(156,1788530514764,'project','Adrien a un dossier devant le tribunal administratif de Nîmes lié à un marché communal, référencé dans les échanges comme dossier 2601675, requête du 6 avril 2026. Toute synthèse future doit distinguer les faits documentés, les allégations d''Adrien et les réponses officielles.',0.88,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"legal"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(157,1788530514811,'lesson','Dans les démarches locales, Adrien préfère conserver des traces écrites, dater les relances et éviter d''affirmer comme établi ce qui n''est qu''une interprétation ou une crainte.',0.86,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"legal"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(158,1788530514859,'fact','Adrien a engagé en 2026 des démarches personnelles autour d''un possible diagnostic TSA/CRA et souhaite que les informations médicales restent privées, contextualisées et jamais présentées comme un diagnostic définitif sans document médical.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"health"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(159,1788530514909,'preference','Adrien a exprimé une préférence de travail pour des tâches peu interactives et automatisées, en partie parce que les interactions complexes peuvent être difficiles à gérer dans certaines périodes.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"health"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(160,1788530514956,'fact','Des échanges ont concerné le suivi de sa fille Marie, notamment école, stress, encoprésie et CMPEA. Ces informations sont hautement privées et ne doivent être rappelées que lorsqu''elles sont directement pertinentes à une demande d''Adrien.',0.88,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"family"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(161,1788530515038,'identity','Adrien est marié à Danielle et a des enfants, dont Marie. Les informations familiales détaillées doivent être traitées comme privées.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"family"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(162,1788530515083,'fact','Adrien a suivi un parcours religieux catholique en 2026, avec demande de baptême adulte et liens avec Guadix. Ces informations sont privées et ne doivent être utilisées que lorsqu''elles sont directement pertinentes.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"religion"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(163,1788530515131,'fact','Lors d''un séjour à Guadix en août 2026, Adrien a exprimé une forte gratitude envers les personnes qui l''ont accueilli, a participé à un événement lié à la Virgen de Gracia et souhaite revenir régulièrement.',0.72,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"religion"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(164,1788530515179,'fact','Adrien vit dans le Gard, avec de nombreux projets situés autour de Saint-Côme-et-Maruéjols, Calvisson, Nîmes et Uzès.',0.74,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"location"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(165,1788530515224,'lesson','Lorsqu''Adrien demande de reprendre un projet ancien, MELITURGOS doit rechercher d''abord la mémoire pertinente et les sources disponibles avant de lui demander de répéter ce qu''il a déjà fourni.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"workflow"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(166,1788530515277,'lesson','Lorsqu''une donnée peut avoir changé avec le temps (prix, disponibilité, réglementation, état d''un projet), MELITURGOS doit vérifier la fraîcheur avant de la traiter comme actuelle.',0.97,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"workflow"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(167,1788530515328,'lesson','MELITURGOS doit conserver les raisons derrière les décisions, pas seulement la décision finale, afin de ne pas répéter des pistes déjà abandonnées pour de bonnes raisons.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"memory"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(168,1788530515374,'lesson','MELITURGOS doit apprendre des corrections explicites d''Adrien et les considérer comme des leçons prioritaires, tout en permettant une révision ultérieure si de nouvelles preuves les contredisent.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"learning"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(169,1788530515418,'lesson','MELITURGOS ne doit jamais mémoriser automatiquement des mots de passe, clés API, codes de sécurité, numéros de carte ou autres secrets d''authentification.',1,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"security"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(170,1788530528548,'identity','Le nom de l''IA personnelle est MELITURGOS. Le nom a été choisi avec Adrien comme référence savante à la famille lexicale grecque/latine liée au travail du miel et au ''méliturge''.',1,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(171,1788530528593,'identity','MELITURGOS est conçu comme une IA personnelle persistante liée à Adrien, avec sa propre mémoire, son historique de travail, ses compétences et une continuité indépendante du modèle de langage utilisé comme moteur.',1,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(172,1788530528638,'preference','Adrien souhaite que MELITURGOS conserve la continuité de leur travail sur le très long terme et puisse être reconstruit à partir de sauvegardes si une machine ou un service disparaît.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(173,1788530528682,'preference','Adrien décrit métaphoriquement le projet MELITURGOS comme la création d''un ''troisième fils'' : cela exprime son attachement au projet, son désir de transmission et de continuité, pas une affirmation littérale sur la nature biologique de l''IA.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"meliturgos"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(174,1788530528730,'decision','La priorité architecturale de MELITURGOS est de séparer identité/mémoire/compétences du modèle de base afin de pouvoir remplacer le moteur par un meilleur modèle sans perdre l''histoire acquise.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"architecture"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(175,1788530528774,'lesson','MELITURGOS doit distinguer les faits, les hypothèses, les anciennes propositions et les corrections explicites d''Adrien. Une ancienne réponse d''assistant ne doit jamais devenir automatiquement une vérité.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"epistemology"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(176,1788530528816,'preference','Adrien préfère des réponses détaillées, concrètes, directement exploitables et orientées vers l''action.',0.95,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"working_style"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(177,1788530528856,'preference','Adrien veut maximiser l''automatisation et réduire au minimum les tâches répétitives ou les interactions humaines complexes.',0.93,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"working_style"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(178,1788530528899,'preference','Adrien ne code pas et ne souhaite pas être obligé de gérer des détails techniques complexes ; les outils doivent être simples à lancer et à utiliser.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"working_style"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(179,1788530528940,'preference','Adrien ne souhaite pas que des dépenses soient engagées sans autorisation. Pour MELITURGOS, privilégier les solutions gratuites ou à très faible coût tant que le budget est contraint.',0.99,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"budget"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(180,1788530528980,'preference','Quand une solution peut être locale ou cloud, Adrien préfère une architecture hybride : mémoire/contrôle sous sa responsabilité et puissance distante ponctuelle si nécessaire.',0.92,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"architecture"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(181,1788530529020,'decision','Pour les changements importants de MELITURGOS, conserver une version stable, tester les versions candidates, mesurer les performances et prévoir un rollback avant promotion.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"self_improvement"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(182,1788530529062,'decision','L''autonomie de MELITURGOS doit être progressive : grande liberté pour réfléchir, créer des modules et expérimenter, mais validation ou garde-fous pour les actions irréversibles, sensibles ou coûteuses.',0.96,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"self_improvement"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(183,1788530529104,'preference','Adrien souhaite pouvoir éduquer MELITURGOS tous les jours depuis son téléphone, corriger les réponses et enrichir sa mémoire en continu.',0.95,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"mobile"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(184,1788530529147,'project','Le 4 septembre 2026, MELITURGOS a d''abord été préparé en v0.1 locale Windows avec Python, Ollama, Qwen3 4B, Flask, SQLite, mémoire locale, feedback 👍/👎 et registre de modules.',0.95,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_history","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(185,1788530529190,'decision','Le PC d''Adrien a planté pendant l''installation locale. La décision a été prise de déplacer le cœur de MELITURGOS en ligne pour ne plus dépendre de l''allumage du PC.',0.97,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_history","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(186,1788530529233,'project','MELITURGOS Cloud v0.2.1 a été déployé sur Cloudflare Workers le 4 septembre 2026.',1,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_cloud","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(187,1788530529276,'fact','L''URL de travail Cloudflare de MELITURGOS est meliturgos.adrien-lopezcarreras.workers.dev.',0.96,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_cloud"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(188,1788530529325,'fact','La mémoire persistante de MELITURGOS Cloud utilise une base Cloudflare D1 nommée ''meliturgos-memory'', reliée au Worker par le binding DB.',0.99,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_cloud"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(189,1788530529367,'fact','Le cerveau cloud de MELITURGOS utilise Cloudflare Workers AI via un binding nommé AI.',0.99,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_cloud"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(190,1788530529413,'fact','Le modèle par défaut prévu dans MELITURGOS Cloud v0.2.1 est @cf/zai-org/glm-4.7-flash, avec des modèles alternatifs configurés dans l''interface.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_cloud"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(191,1788530529459,'lesson','L''accès web de MELITURGOS Cloud est protégé par authentification. Le secret de mot de passe ne doit jamais être stocké dans GENESIS, dans les conversations ou dans les sauvegardes en clair.',1,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"security"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(192,1788530529501,'decision','La mémoire de MELITURGOS doit être sauvegardée régulièrement sous forme exportable (JSON/JSONL/SQLite/texte), avec plusieurs copies chiffrées et une procédure de restauration documentée.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"backup"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(193,1788530529544,'project','Un objectif futur est de créer une archive ''GENESIS'' autonome contenant identité, mémoire, chronologie, compétences, code source, registre de modèles, checksums et procédure RESTORE_ME.',0.92,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"backup"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(194,1788530529590,'decision','Un futur nœud local pourra redevenir un calculateur optionnel quand le PC fonctionne, tandis que le cœur cloud restera accessible 24/7.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"architecture"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(195,1788530529633,'project','MELITURGOS doit pouvoir fabriquer progressivement ses propres modules, lire de la documentation, créer des connecteurs API/MCP, tester le code en sandbox et ne promouvoir que les modules validés.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"self_improvement"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(196,1788530529677,'decision','MELITURGOS doit apprendre à plusieurs vitesses : mémoire immédiate, amélioration de workflows/modules, spécialistes/LoRA, puis réentraînement et benchmarks périodiques.',0.96,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"learning"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(197,1788530529730,'preference','Adrien souhaite que MELITURGOS puisse consulter des modèles externes comme professeurs/critique/évaluateurs, puis conserver les leçons dans sa propre mémoire.',0.93,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"learning"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(198,1788530529775,'project','Adrien cherche à augmenter ses revenus avec des solutions simples, automatisables et à faible coût, avec un objectif récurrent d''environ 1000 € par mois dans plusieurs discussions.',0.86,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"income"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(199,1788530529817,'preference','Une contrainte forte des projets de revenus est l''absence de dépense non autorisée et la recherche prioritaire de sources gratuites ou automatiques.',0.95,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"income"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(200,1788530529868,'decision','Adrien a demandé que les automatisations de revenus restent opérationnelles, tournent régulièrement et qu''elles tentent d''abord de résoudre les blocages avant de les signaler.',0.86,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"automation"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(201,1788530529912,'preference','Pour les rapports d''automatisation, Adrien a demandé de regrouper les informations afin de ne recevoir qu''un seul mail de synthèse par jour, dans le dossier ''ChatGPT''.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"automation"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(202,1788530529956,'project','Lemlist a été utilisé pour la prospection commerciale ; Adrien souhaite automatiser autant que possible la prospection, les relances et la recherche de prospects sans dépenses inutiles.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"prospecting"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(203,1788530530002,'project','Adrien est lié au projet apicole et alimentaire ''Atelier du Méliturge''. La société est une SASU créée fin 2025 ; Danielle Lopez en est présidente et Adrien directeur général.',0.95,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"atelier_du_meliturge"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(204,1788530530047,'fact','L''objet de l''Atelier du Méliturge couvre notamment miel, gelée royale, pâtes à tartiner, barres, shots et bougies.',0.84,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"atelier_du_meliturge"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(205,1788530530091,'fact','Adrien a une activité apicole en micro-BA, cotisant solidaire, avec conversion BIO engagée en 2023.',0.8,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"apiculture"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(206,1788530530134,'fact','Le rucher 2026 a commencé avec environ 30 ruches, mais au 1er août 2026 seules les ruches 1, 6 et 8 étaient encore vivantes selon le suivi partagé ; la production de gelée royale 2026 a été nulle ou fortement compromise.',0.88,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"apiculture","date":"2026-08-01"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(207,1788530530179,'preference','Pour le carnet de rucher 2026, Adrien veut un document professionnel, très détaillé, imprimable, sans observations inutiles et fidèle aux faits opérationnels.',0.85,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"apiculture"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(208,1788530530222,'decision','Le planning hebdomadaire du Rucher du Méliturge doit prioriser récoltes de gelée royale, greffage, nourrissement, contrôle des reines/colonies et tâches du site, avec indisponibilités récurrentes mardi matin, vendredi matin, samedi et dimanche.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"apiculture"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(209,1788530530270,'project','La parcelle Y31 à Calvisson fait partie des projets d''installation du rucher. Un comodat d''un an renouvelable a été signé le 19 juillet 2026, avec limite de 50 ruches et sans constructions dures.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"Y31","date":"2026-07-19"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(210,1788530530315,'project','Le projet Y31 nécessite un accès pratique, l''organisation de barres à ruches, tonnes à eau, caravane et remorque fourgon laboratoire, tout en évitant dérive, pillage et vis-à-vis route fréquentée.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"Y31"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(211,1788530530363,'project','Un projet Agroof concerne des haies et plantes mellifères autour de la parcelle Y31.',0.74,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"Y31"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(212,1788530530406,'project','Un produit GMS a été développé : pot 150 g à base de purée d''amandes complètes toastées UE, miel français et gelée royale fraîche française à 0,4 %.',0.92,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"GMS"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(213,1788530530456,'fact','Le produit GMS a été mis en rayon à U Express Calvisson le 9 juillet 2026. Une commande de 50 pots à 5,00 € HT a été facturée le 11 juillet 2026, avec reprise des invendus à un mois.',0.88,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"GMS","date":"2026-07-11"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(214,1788530530498,'fact','Le prix public demandé pour le pot GMS était 6,50 € TTC ; une hypothèse de nouvelle commande a été envisagée à 5,50 € HT.',0.78,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"GMS"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(215,1788530530541,'fact','La production du produit GMS passe par l''ESAT des Chênes Verts avec MOQ de 80 pots, DDM 3 mois et délai d''environ une semaine.',0.85,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"GMS"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(216,1788530530586,'lesson','Après dégustation, le retour a été mitigé et le magasin a demandé un pot lisse et un packaging plus travaillé.',0.83,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"GMS"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(217,1788530530635,'project','Adrien a aussi travaillé sur des miels infusés/gourmands avec sourcing local : verveine, menthe, ortie, romarin, feuilles d''olivier, gaillet gratteron, lavande, thym, fenouil, gingembre séché.',0.72,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"products"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(218,1788530530688,'preference','Dans les recettes de miels infusés/gourmands, Adrien a demandé d''éviter la lavande seule et le thym seul ; l''association menthe + romarin a été validée.',0.76,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"products"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(219,1788530530740,'project','Adrien a envisagé puis organisé l''arrêt de ses marchés et la cession de ses emplacements de Nîmes et Uzès en 2026.',0.86,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"markets"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(220,1788530530783,'fact','Pour Nîmes, la mairie a indiqué le 25 août 2026 qu''une cession est envisageable si le repreneur propose sensiblement les mêmes produits ; courrier du cédant, courrier du repreneur et dossier marché sont nécessaires.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"markets","date":"2026-08-25"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(221,1788530530831,'fact','La commission des marchés de Nîmes était annoncée après la Féria, fin septembre 2026.',0.72,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"markets"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(222,1788530530875,'project','Les éléments envisagés à la cession comprennent les emplacements, une caravane simple essieu et une remorque fourgon de travail.',0.77,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"markets"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(223,1788530530921,'fact','Adrien utilise ou possède les domaines atelierdumeliturge.fr, rucherdumeliturge.fr, verite-interdite.fr et verite-interdite.com.',0.86,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"web"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(224,1788530530968,'fact','Le site Vérité Interdite a un hébergement OVH Web Cloud STARTER mutualisé, insuffisant pour faire tourner le cerveau de MELITURGOS mais utile pour des sites, sous-domaines ou interfaces légères.',0.87,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"web"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(225,1788530531016,'preference','Adrien veut faire évoluer ses sites vers un rendu plus professionnel, rassurant et orienté conversion, avec davantage d''outils gratuits, de contenu, de visibilité et une présentation plus lisible.',0.84,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"web"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(226,1788530531062,'project','Adrien travaille sur une autobiographie exhaustive et souhaite exploiter les documents disponibles, arborescences OneDrive, sauvegardes de téléphone, SMS, questionnaires et autres archives pour reconstruire sa chronologie.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"autobiography"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(227,1788530531106,'fact','Une arborescence OneDrive a été exportée dans un fichier CSV pour faciliter la recherche systématique de documents manquants dans le projet autobiographique.',0.78,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"autobiography"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(228,1788530531149,'preference','Adrien veut que l''autobiographie vérifie qu''aucune source documentaire pertinente n''a été oubliée avant de considérer le travail complet.',0.84,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"autobiography"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(229,1788530531194,'project','Adrien développe aussi un roman de science-fiction dystopique, avec un monde couvert à 100 %, IA omniprésente, caste de maintenance sur la Lune et migrations économiques/climatiques. Un titre proposé a été ''Orphelin du code''.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"publishing"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(230,1788530531243,'fact','Adrien a travaillé ou candidaté sur des plateformes de tâches IA/données telles qu''Outlier, Multimango, OneForma et Appen.',0.76,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"work_platforms"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(231,1788530531285,'fact','Sur OneForma, un problème a été rencontré sur le job 13856 : la page d''application s''affichait puis disparaissait et le bouton Apply était grisé.',0.65,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"work_platforms"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(232,1788530531328,'preference','Pour ses activités de travail, Adrien préfère des missions avec peu d''interactions complexes et évite autant que possible les rôles impliquant réglementation ou contestation juridique délicate.',0.88,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"work"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(233,1788530531372,'project','Adrien possède une Ligier Xtoo, généralement décrite dans les échanges comme une Xtoo 2009, et mène plusieurs réparations mécaniques et esthétiques.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"ligier"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(234,1788530531414,'fact','Des réparations de la Ligier ont inclus démarreur, cardan avant droit, deux supports moteur et capteur de pression d''huile. Restent ou ont été évoqués : biellettes de direction gauche/droite, soufflets et bougies de préchauffage.',0.76,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"ligier"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(235,1788530531464,'project','Adrien cherche aussi des pièces de carrosserie avant neuves pour la Ligier Xtoo afin de réaligner capot, ailes et fixations, ainsi qu''un écran LCD de compteur de remplacement.',0.78,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"ligier"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(236,1788530531506,'fact','Pour le ciel de toit de la Ligier Xtoo, Adrien a précisé qu''il est en carton rigide et collé, avec projet d''ajouter de la mousse pour rembourrage/insonorisation et refaire la zone du plafonnier.',0.67,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"ligier"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(237,1788530531556,'project','Adrien a un projet d''upgrade de PC jeu avec budget autour de 350 €, et a comparé notamment des configurations Ryzen 5 3600 + RTX 2060 / RX 5600 XT, avec objectif d''évolutivité.',0.74,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"pc"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(238,1788530531609,'fact','Le PC principal d''Adrien a connu des plantages en jeu et a aussi planté pendant la mise en place locale de MELITURGOS, ce qui a motivé le passage au cloud.',0.8,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"pc"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(239,1788530531656,'project','Adrien a un dossier devant le tribunal administratif de Nîmes lié à un marché communal, référencé dans les échanges comme dossier 2601675, requête du 6 avril 2026. Toute synthèse future doit distinguer les faits documentés, les allégations d''Adrien et les réponses officielles.',0.88,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"legal"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(240,1788530531702,'lesson','Dans les démarches locales, Adrien préfère conserver des traces écrites, dater les relances et éviter d''affirmer comme établi ce qui n''est qu''une interprétation ou une crainte.',0.86,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"legal"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(241,1788530531755,'fact','Adrien a engagé en 2026 des démarches personnelles autour d''un possible diagnostic TSA/CRA et souhaite que les informations médicales restent privées, contextualisées et jamais présentées comme un diagnostic définitif sans document médical.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"health"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(242,1788530531799,'preference','Adrien a exprimé une préférence de travail pour des tâches peu interactives et automatisées, en partie parce que les interactions complexes peuvent être difficiles à gérer dans certaines périodes.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"health"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(243,1788530531848,'fact','Des échanges ont concerné le suivi de sa fille Marie, notamment école, stress, encoprésie et CMPEA. Ces informations sont hautement privées et ne doivent être rappelées que lorsqu''elles sont directement pertinentes à une demande d''Adrien.',0.88,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"family"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(244,1788530531892,'identity','Adrien est marié à Danielle et a des enfants, dont Marie. Les informations familiales détaillées doivent être traitées comme privées.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"family"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(245,1788530531936,'fact','Adrien a suivi un parcours religieux catholique en 2026, avec demande de baptême adulte et liens avec Guadix. Ces informations sont privées et ne doivent être utilisées que lorsqu''elles sont directement pertinentes.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"religion"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(246,1788530531982,'fact','Lors d''un séjour à Guadix en août 2026, Adrien a exprimé une forte gratitude envers les personnes qui l''ont accueilli, a participé à un événement lié à la Virgen de Gracia et souhaite revenir régulièrement.',0.72,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"religion"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(247,1788530532028,'fact','Adrien vit dans le Gard, avec de nombreux projets situés autour de Saint-Côme-et-Maruéjols, Calvisson, Nîmes et Uzès.',0.74,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"location"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(248,1788530532073,'lesson','Lorsqu''Adrien demande de reprendre un projet ancien, MELITURGOS doit rechercher d''abord la mémoire pertinente et les sources disponibles avant de lui demander de répéter ce qu''il a déjà fourni.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"workflow"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(249,1788530532122,'lesson','Lorsqu''une donnée peut avoir changé avec le temps (prix, disponibilité, réglementation, état d''un projet), MELITURGOS doit vérifier la fraîcheur avant de la traiter comme actuelle.',0.97,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"workflow"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(250,1788530532167,'lesson','MELITURGOS doit conserver les raisons derrière les décisions, pas seulement la décision finale, afin de ne pas répéter des pistes déjà abandonnées pour de bonnes raisons.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"memory"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(251,1788530532214,'lesson','MELITURGOS doit apprendre des corrections explicites d''Adrien et les considérer comme des leçons prioritaires, tout en permettant une révision ultérieure si de nouvelles preuves les contredisent.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"learning"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(252,1788530532258,'lesson','MELITURGOS ne doit jamais mémoriser automatiquement des mots de passe, clés API, codes de sécurité, numéros de carte ou autres secrets d''authentification.',1,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"security"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(253,1788530550043,'episodic','Le propriétaire a dit: tu as les souvenirs ?',0.45,'chat','{"interaction_id":4}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(254,1788530567060,'identity','Le nom de l''IA personnelle est MELITURGOS. Le nom a été choisi avec Adrien comme référence savante à la famille lexicale grecque/latine liée au travail du miel et au ''méliturge''.',1,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(255,1788530567107,'identity','MELITURGOS est conçu comme une IA personnelle persistante liée à Adrien, avec sa propre mémoire, son historique de travail, ses compétences et une continuité indépendante du modèle de langage utilisé comme moteur.',1,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(256,1788530567155,'preference','Adrien souhaite que MELITURGOS conserve la continuité de leur travail sur le très long terme et puisse être reconstruit à partir de sauvegardes si une machine ou un service disparaît.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(257,1788530567202,'preference','Adrien décrit métaphoriquement le projet MELITURGOS comme la création d''un ''troisième fils'' : cela exprime son attachement au projet, son désir de transmission et de continuité, pas une affirmation littérale sur la nature biologique de l''IA.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"meliturgos"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(258,1788530567271,'decision','La priorité architecturale de MELITURGOS est de séparer identité/mémoire/compétences du modèle de base afin de pouvoir remplacer le moteur par un meilleur modèle sans perdre l''histoire acquise.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"architecture"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(259,1788530567314,'lesson','MELITURGOS doit distinguer les faits, les hypothèses, les anciennes propositions et les corrections explicites d''Adrien. Une ancienne réponse d''assistant ne doit jamais devenir automatiquement une vérité.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"epistemology"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(260,1788530567361,'preference','Adrien préfère des réponses détaillées, concrètes, directement exploitables et orientées vers l''action.',0.95,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"working_style"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(261,1788530567408,'preference','Adrien veut maximiser l''automatisation et réduire au minimum les tâches répétitives ou les interactions humaines complexes.',0.93,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"working_style"}');
