INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(319,1788530568903,'preference','Adrien ne souhaite pas que des dépenses soient engagées sans autorisation. Pour MELITURGOS, privilégier les solutions gratuites ou à très faible coût tant que le budget est contraint.',0.99,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"budget"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(320,1788530568906,'fact','Le modèle par défaut prévu dans MELITURGOS Cloud v0.2.1 est @cf/zai-org/glm-4.7-flash, avec des modèles alternatifs configurés dans l''interface.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_cloud"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(321,1788530568899,'fact','Le rucher 2026 a commencé avec environ 30 ruches, mais au 1er août 2026 seules les ruches 1, 6 et 8 étaient encore vivantes selon le suivi partagé ; la production de gelée royale 2026 a été nulle ou fortement compromise.',0.88,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"apiculture","date":"2026-08-01"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(322,1788530568969,'preference','Quand une solution peut être locale ou cloud, Adrien préfère une architecture hybride : mémoire/contrôle sous sa responsabilité et puissance distante ponctuelle si nécessaire.',0.92,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"architecture"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(323,1788530568972,'lesson','L''accès web de MELITURGOS Cloud est protégé par authentification. Le secret de mot de passe ne doit jamais être stocké dans GENESIS, dans les conversations ou dans les sauvegardes en clair.',1,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"security"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(324,1788530568960,'preference','Pour le carnet de rucher 2026, Adrien veut un document professionnel, très détaillé, imprimable, sans observations inutiles et fidèle aux faits opérationnels.',0.85,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"apiculture"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(325,1788530569039,'decision','Pour les changements importants de MELITURGOS, conserver une version stable, tester les versions candidates, mesurer les performances et prévoir un rollback avant promotion.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"self_improvement"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(326,1788530569011,'decision','Le planning hebdomadaire du Rucher du Méliturge doit prioriser récoltes de gelée royale, greffage, nourrissement, contrôle des reines/colonies et tâches du site, avec indisponibilités récurrentes mardi matin, vendredi matin, samedi et dimanche.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"apiculture"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(327,1788530569037,'decision','La mémoire de MELITURGOS doit être sauvegardée régulièrement sous forme exportable (JSON/JSONL/SQLite/texte), avec plusieurs copies chiffrées et une procédure de restauration documentée.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"backup"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(328,1788530569089,'decision','L''autonomie de MELITURGOS doit être progressive : grande liberté pour réfléchir, créer des modules et expérimenter, mais validation ou garde-fous pour les actions irréversibles, sensibles ou coûteuses.',0.96,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"self_improvement"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(329,1788530569063,'project','La parcelle Y31 à Calvisson fait partie des projets d''installation du rucher. Un comodat d''un an renouvelable a été signé le 19 juillet 2026, avec limite de 50 ruches et sans constructions dures.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"Y31","date":"2026-07-19"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(330,1788530569094,'project','Un objectif futur est de créer une archive ''GENESIS'' autonome contenant identité, mémoire, chronologie, compétences, code source, registre de modèles, checksums et procédure RESTORE_ME.',0.92,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"backup"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(331,1788530569134,'preference','Adrien souhaite pouvoir éduquer MELITURGOS tous les jours depuis son téléphone, corriger les réponses et enrichir sa mémoire en continu.',0.95,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"mobile"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(332,1788530569120,'project','Le projet Y31 nécessite un accès pratique, l''organisation de barres à ruches, tonnes à eau, caravane et remorque fourgon laboratoire, tout en évitant dérive, pillage et vis-à-vis route fréquentée.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"Y31"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(333,1788530569179,'project','Le 4 septembre 2026, MELITURGOS a d''abord été préparé en v0.1 locale Windows avec Python, Ollama, Qwen3 4B, Flask, SQLite, mémoire locale, feedback 👍/👎 et registre de modules.',0.95,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_history","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(334,1788530569166,'decision','Un futur nœud local pourra redevenir un calculateur optionnel quand le PC fonctionne, tandis que le cœur cloud restera accessible 24/7.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"architecture"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(335,1788530569167,'project','Un projet Agroof concerne des haies et plantes mellifères autour de la parcelle Y31.',0.74,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"Y31"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(336,1788530569228,'project','MELITURGOS doit pouvoir fabriquer progressivement ses propres modules, lire de la documentation, créer des connecteurs API/MCP, tester le code en sandbox et ne promouvoir que les modules validés.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"self_improvement"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(337,1788530569240,'decision','Le PC d''Adrien a planté pendant l''installation locale. La décision a été prise de déplacer le cœur de MELITURGOS en ligne pour ne plus dépendre de l''allumage du PC.',0.97,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_history","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(338,1788530569221,'project','Un produit GMS a été développé : pot 150 g à base de purée d''amandes complètes toastées UE, miel français et gelée royale fraîche française à 0,4 %.',0.92,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"GMS"}');
