INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(340,1788530569316,'project','MELITURGOS Cloud v0.2.1 a été déployé sur Cloudflare Workers le 4 septembre 2026.',1,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_cloud","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(341,1788530569295,'fact','Le produit GMS a été mis en rayon à U Express Calvisson le 9 juillet 2026. Une commande de 50 pots à 5,00 € HT a été facturée le 11 juillet 2026, avec reprise des invendus à un mois.',0.88,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"GMS","date":"2026-07-11"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(342,1788530569348,'preference','Adrien souhaite que MELITURGOS puisse consulter des modèles externes comme professeurs/critique/évaluateurs, puis conserver les leçons dans sa propre mémoire.',0.93,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"learning"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(343,1788530569383,'fact','L''URL de travail Cloudflare de MELITURGOS est meliturgos.adrien-lopezcarreras.workers.dev.',0.96,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_cloud"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(344,1788530569361,'fact','Le prix public demandé pour le pot GMS était 6,50 € TTC ; une hypothèse de nouvelle commande a été envisagée à 5,50 € HT.',0.78,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"GMS"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(345,1788530569417,'project','Adrien cherche à augmenter ses revenus avec des solutions simples, automatisables et à faible coût, avec un objectif récurrent d''environ 1000 € par mois dans plusieurs discussions.',0.86,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"income"}');
