INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(382,1788530570259,'decision','Adrien a demandé que les automatisations de revenus restent opérationnelles, tournent régulièrement et qu''elles tentent d''abord de résoudre les blocages avant de les signaler.',0.86,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"automation"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(383,1788530570274,'project','Un projet Agroof concerne des haies et plantes mellifères autour de la parcelle Y31.',0.74,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"Y31"}');
