INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(411,1788530570820,'fact','Pour Nîmes, la mairie a indiqué le 25 août 2026 qu''une cession est envisageable si le repreneur propose sensiblement les mêmes produits ; courrier du cédant, courrier du repreneur et dossier marché sont nécessaires.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"markets","date":"2026-08-25"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(412,1788530570836,'fact','Pour le ciel de toit de la Ligier Xtoo, Adrien a précisé qu''il est en carton rigide et collé, avec projet d''ajouter de la mousse pour rembourrage/insonorisation et refaire la zone du plafonnier.',0.67,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"ligier"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(413,1788530570867,'project','Un projet Agroof concerne des haies et plantes mellifères autour de la parcelle Y31.',0.74,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"Y31"}');
