INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(418,1788530570959,'fact','Le PC principal d''Adrien a connu des plantages en jeu et a aussi planté pendant la mise en place locale de MELITURGOS, ce qui a motivé le passage au cloud.',0.8,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"pc"}');
