INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(443,1788530571480,'fact','Lors d''un séjour à Guadix en août 2026, Adrien a exprimé une forte gratitude envers les personnes qui l''ont accueilli, a participé à un événement lié à la Virgen de Gracia et souhaite revenir régulièrement.',0.72,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"religion"}');
