INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(445,1788530571502,'project','Les éléments envisagés à la cession comprennent les emplacements, une caravane simple essieu et une remorque fourgon de travail.',0.77,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"markets"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(446,1788530571524,'fact','Adrien vit dans le Gard, avec de nombreux projets situés autour de Saint-Côme-et-Maruéjols, Calvisson, Nîmes et Uzès.',0.74,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"location"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(447,1788530571546,'preference','Pour ses activités de travail, Adrien préfère des missions avec peu d''interactions complexes et évite autant que possible les rôles impliquant réglementation ou contestation juridique délicate.',0.88,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"work"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(448,1788530571572,'fact','Adrien utilise ou possède les domaines atelierdumeliturge.fr, rucherdumeliturge.fr, verite-interdite.fr et verite-interdite.com.',0.86,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"web"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(449,1788530571578,'lesson','Lorsqu''Adrien demande de reprendre un projet ancien, MELITURGOS doit rechercher d''abord la mémoire pertinente et les sources disponibles avant de lui demander de répéter ce qu''il a déjà fourni.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"workflow"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(450,1788530571592,'project','Adrien possède une Ligier Xtoo, généralement décrite dans les échanges comme une Xtoo 2009, et mène plusieurs réparations mécaniques et esthétiques.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"ligier"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(451,1788530571623,'fact','Le site Vérité Interdite a un hébergement OVH Web Cloud STARTER mutualisé, insuffisant pour faire tourner le cerveau de MELITURGOS mais utile pour des sites, sous-domaines ou interfaces légères.',0.87,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"web"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(452,1788530571646,'lesson','Lorsqu''une donnée peut avoir changé avec le temps (prix, disponibilité, réglementation, état d''un projet), MELITURGOS doit vérifier la fraîcheur avant de la traiter comme actuelle.',0.97,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"workflow"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(453,1788530571659,'fact','Des réparations de la Ligier ont inclus démarreur, cardan avant droit, deux supports moteur et capteur de pression d''huile. Restent ou ont été évoqués : biellettes de direction gauche/droite, soufflets et bougies de préchauffage.',0.76,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"ligier"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(454,1788530571693,'preference','Adrien veut faire évoluer ses sites vers un rendu plus professionnel, rassurant et orienté conversion, avec davantage d''outils gratuits, de contenu, de visibilité et une présentation plus lisible.',0.84,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"web"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(455,1788530571717,'lesson','MELITURGOS doit conserver les raisons derrière les décisions, pas seulement la décision finale, afin de ne pas répéter des pistes déjà abandonnées pour de bonnes raisons.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"memory"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(456,1788530571707,'project','Adrien cherche aussi des pièces de carrosserie avant neuves pour la Ligier Xtoo afin de réaligner capot, ailes et fixations, ainsi qu''un écran LCD de compteur de remplacement.',0.78,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"ligier"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(457,1788530571736,'project','Adrien travaille sur une autobiographie exhaustive et souhaite exploiter les documents disponibles, arborescences OneDrive, sauvegardes de téléphone, SMS, questionnaires et autres archives pour reconstruire sa chronologie.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"autobiography"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(458,1788530571769,'lesson','MELITURGOS doit apprendre des corrections explicites d''Adrien et les considérer comme des leçons prioritaires, tout en permettant une révision ultérieure si de nouvelles preuves les contredisent.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"learning"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(459,1788530571780,'fact','Pour le ciel de toit de la Ligier Xtoo, Adrien a précisé qu''il est en carton rigide et collé, avec projet d''ajouter de la mousse pour rembourrage/insonorisation et refaire la zone du plafonnier.',0.67,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"ligier"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(460,1788530571789,'fact','Une arborescence OneDrive a été exportée dans un fichier CSV pour faciliter la recherche systématique de documents manquants dans le projet autobiographique.',0.78,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"autobiography"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(461,1788530571811,'lesson','MELITURGOS ne doit jamais mémoriser automatiquement des mots de passe, clés API, codes de sécurité, numéros de carte ou autres secrets d''authentification.',1,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"security"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(462,1788530571834,'project','Adrien a un projet d''upgrade de PC jeu avec budget autour de 350 €, et a comparé notamment des configurations Ryzen 5 3600 + RTX 2060 / RX 5600 XT, avec objectif d''évolutivité.',0.74,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"pc"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(463,1788530571859,'preference','Adrien veut que l''autobiographie vérifie qu''aucune source documentaire pertinente n''a été oubliée avant de considérer le travail complet.',0.84,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"autobiography"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(464,1788530571886,'fact','Le PC principal d''Adrien a connu des plantages en jeu et a aussi planté pendant la mise en place locale de MELITURGOS, ce qui a motivé le passage au cloud.',0.8,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"pc"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(465,1788530571920,'project','Adrien développe aussi un roman de science-fiction dystopique, avec un monde couvert à 100 %, IA omniprésente, caste de maintenance sur la Lune et migrations économiques/climatiques. Un titre proposé a été ''Orphelin du code''.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"publishing"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(466,1788530571952,'project','Adrien a un dossier devant le tribunal administratif de Nîmes lié à un marché communal, référencé dans les échanges comme dossier 2601675, requête du 6 avril 2026. Toute synthèse future doit distinguer les faits documentés, les allégations d''Adrien et les réponses officielles.',0.88,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"legal"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(467,1788530571982,'fact','Adrien a travaillé ou candidaté sur des plateformes de tâches IA/données telles qu''Outlier, Multimango, OneForma et Appen.',0.76,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"work_platforms"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(468,1788530572028,'lesson','Dans les démarches locales, Adrien préfère conserver des traces écrites, dater les relances et éviter d''affirmer comme établi ce qui n''est qu''une interprétation ou une crainte.',0.86,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"legal"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(469,1788530572087,'identity','Le nom de l''IA personnelle est MELITURGOS. Le nom a été choisi avec Adrien comme référence savante à la famille lexicale grecque/latine liée au travail du miel et au ''méliturge''.',1,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(470,1788530572050,'fact','Sur OneForma, un problème a été rencontré sur le job 13856 : la page d''application s''affichait puis disparaissait et le bouton Apply était grisé.',0.65,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"work_platforms"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(471,1788530572075,'fact','Adrien a engagé en 2026 des démarches personnelles autour d''un possible diagnostic TSA/CRA et souhaite que les informations médicales restent privées, contextualisées et jamais présentées comme un diagnostic définitif sans document médical.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"health"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(472,1788530572150,'identity','MELITURGOS est conçu comme une IA personnelle persistante liée à Adrien, avec sa propre mémoire, son historique de travail, ses compétences et une continuité indépendante du modèle de langage utilisé comme moteur.',1,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(473,1788530572106,'preference','Pour ses activités de travail, Adrien préfère des missions avec peu d''interactions complexes et évite autant que possible les rôles impliquant réglementation ou contestation juridique délicate.',0.88,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"work"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(474,1788530572123,'preference','Adrien a exprimé une préférence de travail pour des tâches peu interactives et automatisées, en partie parce que les interactions complexes peuvent être difficiles à gérer dans certaines périodes.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"health"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(475,1788530572197,'preference','Adrien souhaite que MELITURGOS conserve la continuité de leur travail sur le très long terme et puisse être reconstruit à partir de sauvegardes si une machine ou un service disparaît.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(476,1788530572180,'project','Adrien possède une Ligier Xtoo, généralement décrite dans les échanges comme une Xtoo 2009, et mène plusieurs réparations mécaniques et esthétiques.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"ligier"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(477,1788530572200,'fact','Des échanges ont concerné le suivi de sa fille Marie, notamment école, stress, encoprésie et CMPEA. Ces informations sont hautement privées et ne doivent être rappelées que lorsqu''elles sont directement pertinentes à une demande d''Adrien.',0.88,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"family"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(478,1788530572272,'preference','Adrien décrit métaphoriquement le projet MELITURGOS comme la création d''un ''troisième fils'' : cela exprime son attachement au projet, son désir de transmission et de continuité, pas une affirmation littérale sur la nature biologique de l''IA.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"meliturgos"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(479,1788530572255,'fact','Des réparations de la Ligier ont inclus démarreur, cardan avant droit, deux supports moteur et capteur de pression d''huile. Restent ou ont été évoqués : biellettes de direction gauche/droite, soufflets et bougies de préchauffage.',0.76,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"ligier"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(480,1788530572268,'identity','Adrien est marié à Danielle et a des enfants, dont Marie. Les informations familiales détaillées doivent être traitées comme privées.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"family"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(481,1788530572338,'decision','La priorité architecturale de MELITURGOS est de séparer identité/mémoire/compétences du modèle de base afin de pouvoir remplacer le moteur par un meilleur modèle sans perdre l''histoire acquise.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"architecture"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(482,1788530572324,'project','Adrien cherche aussi des pièces de carrosserie avant neuves pour la Ligier Xtoo afin de réaligner capot, ailes et fixations, ainsi qu''un écran LCD de compteur de remplacement.',0.78,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"ligier"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(483,1788530572344,'fact','Adrien a suivi un parcours religieux catholique en 2026, avec demande de baptême adulte et liens avec Guadix. Ces informations sont privées et ne doivent être utilisées que lorsqu''elles sont directement pertinentes.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"religion"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(484,1788530572403,'lesson','MELITURGOS doit distinguer les faits, les hypothèses, les anciennes propositions et les corrections explicites d''Adrien. Une ancienne réponse d''assistant ne doit jamais devenir automatiquement une vérité.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"epistemology"}');
