INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(505,1788530572845,'decision','L''autonomie de MELITURGOS doit être progressive : grande liberté pour réfléchir, créer des modules et expérimenter, mais validation ou garde-fous pour les actions irréversibles, sensibles ou coûteuses.',0.96,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"self_improvement"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(506,1788530572847,'fact','Des échanges ont concerné le suivi de sa fille Marie, notamment école, stress, encoprésie et CMPEA. Ces informations sont hautement privées et ne doivent être rappelées que lorsqu''elles sont directement pertinentes à une demande d''Adrien.',0.88,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"family"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(507,1788530572893,'preference','Adrien souhaite pouvoir éduquer MELITURGOS tous les jours depuis son téléphone, corriger les réponses et enrichir sa mémoire en continu.',0.95,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"mobile"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(508,1788530572895,'identity','Adrien est marié à Danielle et a des enfants, dont Marie. Les informations familiales détaillées doivent être traitées comme privées.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"family"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(509,1788530572944,'project','Le 4 septembre 2026, MELITURGOS a d''abord été préparé en v0.1 locale Windows avec Python, Ollama, Qwen3 4B, Flask, SQLite, mémoire locale, feedback 👍/👎 et registre de modules.',0.95,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_history","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(510,1788530572941,'fact','Adrien a suivi un parcours religieux catholique en 2026, avec demande de baptême adulte et liens avec Guadix. Ces informations sont privées et ne doivent être utilisées que lorsqu''elles sont directement pertinentes.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"religion"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(511,1788530572989,'decision','Le PC d''Adrien a planté pendant l''installation locale. La décision a été prise de déplacer le cœur de MELITURGOS en ligne pour ne plus dépendre de l''allumage du PC.',0.97,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_history","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(512,1788530572998,'fact','Lors d''un séjour à Guadix en août 2026, Adrien a exprimé une forte gratitude envers les personnes qui l''ont accueilli, a participé à un événement lié à la Virgen de Gracia et souhaite revenir régulièrement.',0.72,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"religion"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(513,1788530573041,'project','MELITURGOS Cloud v0.2.1 a été déployé sur Cloudflare Workers le 4 septembre 2026.',1,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_cloud","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(514,1788530573051,'fact','Adrien vit dans le Gard, avec de nombreux projets situés autour de Saint-Côme-et-Maruéjols, Calvisson, Nîmes et Uzès.',0.74,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"location"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(515,1788530573091,'fact','L''URL de travail Cloudflare de MELITURGOS est meliturgos.adrien-lopezcarreras.workers.dev.',0.96,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_cloud"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(516,1788530573102,'lesson','Lorsqu''Adrien demande de reprendre un projet ancien, MELITURGOS doit rechercher d''abord la mémoire pertinente et les sources disponibles avant de lui demander de répéter ce qu''il a déjà fourni.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"workflow"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(517,1788530573139,'fact','La mémoire persistante de MELITURGOS Cloud utilise une base Cloudflare D1 nommée ''meliturgos-memory'', reliée au Worker par le binding DB.',0.99,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_cloud"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(518,1788530573152,'lesson','Lorsqu''une donnée peut avoir changé avec le temps (prix, disponibilité, réglementation, état d''un projet), MELITURGOS doit vérifier la fraîcheur avant de la traiter comme actuelle.',0.97,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"workflow"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(519,1788530573189,'fact','Le cerveau cloud de MELITURGOS utilise Cloudflare Workers AI via un binding nommé AI.',0.99,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_cloud"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(520,1788530573202,'lesson','MELITURGOS doit conserver les raisons derrière les décisions, pas seulement la décision finale, afin de ne pas répéter des pistes déjà abandonnées pour de bonnes raisons.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"memory"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(521,1788530573233,'fact','Le modèle par défaut prévu dans MELITURGOS Cloud v0.2.1 est @cf/zai-org/glm-4.7-flash, avec des modèles alternatifs configurés dans l''interface.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_cloud"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(522,1788530573253,'lesson','MELITURGOS doit apprendre des corrections explicites d''Adrien et les considérer comme des leçons prioritaires, tout en permettant une révision ultérieure si de nouvelles preuves les contredisent.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"learning"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(523,1788530573289,'lesson','L''accès web de MELITURGOS Cloud est protégé par authentification. Le secret de mot de passe ne doit jamais être stocké dans GENESIS, dans les conversations ou dans les sauvegardes en clair.',1,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"security"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(524,1788530573298,'lesson','MELITURGOS ne doit jamais mémoriser automatiquement des mots de passe, clés API, codes de sécurité, numéros de carte ou autres secrets d''authentification.',1,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"security"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(525,1788530573340,'decision','La mémoire de MELITURGOS doit être sauvegardée régulièrement sous forme exportable (JSON/JSONL/SQLite/texte), avec plusieurs copies chiffrées et une procédure de restauration documentée.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"backup"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(526,1788530573384,'project','Un objectif futur est de créer une archive ''GENESIS'' autonome contenant identité, mémoire, chronologie, compétences, code source, registre de modèles, checksums et procédure RESTORE_ME.',0.92,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"backup"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(527,1788530573427,'decision','Un futur nœud local pourra redevenir un calculateur optionnel quand le PC fonctionne, tandis que le cœur cloud restera accessible 24/7.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"architecture"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(528,1788530573483,'project','MELITURGOS doit pouvoir fabriquer progressivement ses propres modules, lire de la documentation, créer des connecteurs API/MCP, tester le code en sandbox et ne promouvoir que les modules validés.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"self_improvement"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(529,1788530573531,'decision','MELITURGOS doit apprendre à plusieurs vitesses : mémoire immédiate, amélioration de workflows/modules, spécialistes/LoRA, puis réentraînement et benchmarks périodiques.',0.96,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"learning"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(530,1788530573580,'preference','Adrien souhaite que MELITURGOS puisse consulter des modèles externes comme professeurs/critique/évaluateurs, puis conserver les leçons dans sa propre mémoire.',0.93,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"learning"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(531,1788530573630,'project','Adrien cherche à augmenter ses revenus avec des solutions simples, automatisables et à faible coût, avec un objectif récurrent d''environ 1000 € par mois dans plusieurs discussions.',0.86,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"income"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(532,1788530573680,'preference','Une contrainte forte des projets de revenus est l''absence de dépense non autorisée et la recherche prioritaire de sources gratuites ou automatiques.',0.95,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"income"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(533,1788530573734,'decision','Adrien a demandé que les automatisations de revenus restent opérationnelles, tournent régulièrement et qu''elles tentent d''abord de résoudre les blocages avant de les signaler.',0.86,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"automation"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(534,1788530573811,'preference','Pour les rapports d''automatisation, Adrien a demandé de regrouper les informations afin de ne recevoir qu''un seul mail de synthèse par jour, dans le dossier ''ChatGPT''.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"automation"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(535,1788530573855,'project','Lemlist a été utilisé pour la prospection commerciale ; Adrien souhaite automatiser autant que possible la prospection, les relances et la recherche de prospects sans dépenses inutiles.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"prospecting"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(536,1788530573900,'project','Adrien est lié au projet apicole et alimentaire ''Atelier du Méliturge''. La société est une SASU créée fin 2025 ; Danielle Lopez en est présidente et Adrien directeur général.',0.95,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"atelier_du_meliturge"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(537,1788530573944,'fact','L''objet de l''Atelier du Méliturge couvre notamment miel, gelée royale, pâtes à tartiner, barres, shots et bougies.',0.84,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"atelier_du_meliturge"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(538,1788530573986,'fact','Adrien a une activité apicole en micro-BA, cotisant solidaire, avec conversion BIO engagée en 2023.',0.8,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"apiculture"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(539,1788530574033,'fact','Le rucher 2026 a commencé avec environ 30 ruches, mais au 1er août 2026 seules les ruches 1, 6 et 8 étaient encore vivantes selon le suivi partagé ; la production de gelée royale 2026 a été nulle ou fortement compromise.',0.88,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"apiculture","date":"2026-08-01"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(540,1788530574078,'preference','Pour le carnet de rucher 2026, Adrien veut un document professionnel, très détaillé, imprimable, sans observations inutiles et fidèle aux faits opérationnels.',0.85,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"apiculture"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(541,1788530574121,'decision','Le planning hebdomadaire du Rucher du Méliturge doit prioriser récoltes de gelée royale, greffage, nourrissement, contrôle des reines/colonies et tâches du site, avec indisponibilités récurrentes mardi matin, vendredi matin, samedi et dimanche.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"apiculture"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(542,1788530574168,'project','La parcelle Y31 à Calvisson fait partie des projets d''installation du rucher. Un comodat d''un an renouvelable a été signé le 19 juillet 2026, avec limite de 50 ruches et sans constructions dures.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"Y31","date":"2026-07-19"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(543,1788530574214,'project','Le projet Y31 nécessite un accès pratique, l''organisation de barres à ruches, tonnes à eau, caravane et remorque fourgon laboratoire, tout en évitant dérive, pillage et vis-à-vis route fréquentée.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"Y31"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(544,1788530574256,'project','Un projet Agroof concerne des haies et plantes mellifères autour de la parcelle Y31.',0.74,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"Y31"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(545,1788530574308,'project','Un produit GMS a été développé : pot 150 g à base de purée d''amandes complètes toastées UE, miel français et gelée royale fraîche française à 0,4 %.',0.92,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"GMS"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(546,1788530574351,'fact','Le produit GMS a été mis en rayon à U Express Calvisson le 9 juillet 2026. Une commande de 50 pots à 5,00 € HT a été facturée le 11 juillet 2026, avec reprise des invendus à un mois.',0.88,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"GMS","date":"2026-07-11"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(547,1788530574395,'fact','Le prix public demandé pour le pot GMS était 6,50 € TTC ; une hypothèse de nouvelle commande a été envisagée à 5,50 € HT.',0.78,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"GMS"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(548,1788530574440,'fact','La production du produit GMS passe par l''ESAT des Chênes Verts avec MOQ de 80 pots, DDM 3 mois et délai d''environ une semaine.',0.85,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"GMS"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(549,1788530574482,'lesson','Après dégustation, le retour a été mitigé et le magasin a demandé un pot lisse et un packaging plus travaillé.',0.83,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"GMS"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(550,1788530574527,'project','Adrien a aussi travaillé sur des miels infusés/gourmands avec sourcing local : verveine, menthe, ortie, romarin, feuilles d''olivier, gaillet gratteron, lavande, thym, fenouil, gingembre séché.',0.72,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"products"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(551,1788530574571,'preference','Dans les recettes de miels infusés/gourmands, Adrien a demandé d''éviter la lavande seule et le thym seul ; l''association menthe + romarin a été validée.',0.76,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"products"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(552,1788530574616,'project','Adrien a envisagé puis organisé l''arrêt de ses marchés et la cession de ses emplacements de Nîmes et Uzès en 2026.',0.86,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"markets"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(553,1788530574662,'fact','Pour Nîmes, la mairie a indiqué le 25 août 2026 qu''une cession est envisageable si le repreneur propose sensiblement les mêmes produits ; courrier du cédant, courrier du repreneur et dossier marché sont nécessaires.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"markets","date":"2026-08-25"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(554,1788530574708,'fact','La commission des marchés de Nîmes était annoncée après la Féria, fin septembre 2026.',0.72,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"markets"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(555,1788530574753,'project','Les éléments envisagés à la cession comprennent les emplacements, une caravane simple essieu et une remorque fourgon de travail.',0.77,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"markets"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(556,1788530574797,'fact','Adrien utilise ou possède les domaines atelierdumeliturge.fr, rucherdumeliturge.fr, verite-interdite.fr et verite-interdite.com.',0.86,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"web"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(557,1788530574844,'fact','Le site Vérité Interdite a un hébergement OVH Web Cloud STARTER mutualisé, insuffisant pour faire tourner le cerveau de MELITURGOS mais utile pour des sites, sous-domaines ou interfaces légères.',0.87,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"web"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(558,1788530574888,'preference','Adrien veut faire évoluer ses sites vers un rendu plus professionnel, rassurant et orienté conversion, avec davantage d''outils gratuits, de contenu, de visibilité et une présentation plus lisible.',0.84,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"web"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(559,1788530574935,'project','Adrien travaille sur une autobiographie exhaustive et souhaite exploiter les documents disponibles, arborescences OneDrive, sauvegardes de téléphone, SMS, questionnaires et autres archives pour reconstruire sa chronologie.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"autobiography"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(560,1788530574978,'fact','Une arborescence OneDrive a été exportée dans un fichier CSV pour faciliter la recherche systématique de documents manquants dans le projet autobiographique.',0.78,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"autobiography"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(561,1788530575024,'preference','Adrien veut que l''autobiographie vérifie qu''aucune source documentaire pertinente n''a été oubliée avant de considérer le travail complet.',0.84,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"autobiography"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(562,1788530575109,'project','Adrien développe aussi un roman de science-fiction dystopique, avec un monde couvert à 100 %, IA omniprésente, caste de maintenance sur la Lune et migrations économiques/climatiques. Un titre proposé a été ''Orphelin du code''.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"publishing"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(563,1788530575157,'fact','Adrien a travaillé ou candidaté sur des plateformes de tâches IA/données telles qu''Outlier, Multimango, OneForma et Appen.',0.76,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"work_platforms"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(564,1788530575207,'fact','Sur OneForma, un problème a été rencontré sur le job 13856 : la page d''application s''affichait puis disparaissait et le bouton Apply était grisé.',0.65,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"work_platforms"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(565,1788530575253,'preference','Pour ses activités de travail, Adrien préfère des missions avec peu d''interactions complexes et évite autant que possible les rôles impliquant réglementation ou contestation juridique délicate.',0.88,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"work"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(566,1788530575299,'project','Adrien possède une Ligier Xtoo, généralement décrite dans les échanges comme une Xtoo 2009, et mène plusieurs réparations mécaniques et esthétiques.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"ligier"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(567,1788530575341,'fact','Des réparations de la Ligier ont inclus démarreur, cardan avant droit, deux supports moteur et capteur de pression d''huile. Restent ou ont été évoqués : biellettes de direction gauche/droite, soufflets et bougies de préchauffage.',0.76,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"ligier"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(568,1788530575384,'project','Adrien cherche aussi des pièces de carrosserie avant neuves pour la Ligier Xtoo afin de réaligner capot, ailes et fixations, ainsi qu''un écran LCD de compteur de remplacement.',0.78,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"ligier"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(569,1788530575436,'fact','Pour le ciel de toit de la Ligier Xtoo, Adrien a précisé qu''il est en carton rigide et collé, avec projet d''ajouter de la mousse pour rembourrage/insonorisation et refaire la zone du plafonnier.',0.67,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"ligier"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(570,1788530575477,'project','Adrien a un projet d''upgrade de PC jeu avec budget autour de 350 €, et a comparé notamment des configurations Ryzen 5 3600 + RTX 2060 / RX 5600 XT, avec objectif d''évolutivité.',0.74,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"pc"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(571,1788530575526,'fact','Le PC principal d''Adrien a connu des plantages en jeu et a aussi planté pendant la mise en place locale de MELITURGOS, ce qui a motivé le passage au cloud.',0.8,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"pc"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(572,1788530575570,'project','Adrien a un dossier devant le tribunal administratif de Nîmes lié à un marché communal, référencé dans les échanges comme dossier 2601675, requête du 6 avril 2026. Toute synthèse future doit distinguer les faits documentés, les allégations d''Adrien et les réponses officielles.',0.88,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"legal"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(573,1788530575620,'lesson','Dans les démarches locales, Adrien préfère conserver des traces écrites, dater les relances et éviter d''affirmer comme établi ce qui n''est qu''une interprétation ou une crainte.',0.86,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"legal"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(574,1788530575663,'fact','Adrien a engagé en 2026 des démarches personnelles autour d''un possible diagnostic TSA/CRA et souhaite que les informations médicales restent privées, contextualisées et jamais présentées comme un diagnostic définitif sans document médical.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"health"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(575,1788530575707,'preference','Adrien a exprimé une préférence de travail pour des tâches peu interactives et automatisées, en partie parce que les interactions complexes peuvent être difficiles à gérer dans certaines périodes.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"health"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(576,1788530575753,'fact','Des échanges ont concerné le suivi de sa fille Marie, notamment école, stress, encoprésie et CMPEA. Ces informations sont hautement privées et ne doivent être rappelées que lorsqu''elles sont directement pertinentes à une demande d''Adrien.',0.88,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"family"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(577,1788530575805,'identity','Adrien est marié à Danielle et a des enfants, dont Marie. Les informations familiales détaillées doivent être traitées comme privées.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"family"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(578,1788530575850,'fact','Adrien a suivi un parcours religieux catholique en 2026, avec demande de baptême adulte et liens avec Guadix. Ces informations sont privées et ne doivent être utilisées que lorsqu''elles sont directement pertinentes.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"religion"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(579,1788530575898,'fact','Lors d''un séjour à Guadix en août 2026, Adrien a exprimé une forte gratitude envers les personnes qui l''ont accueilli, a participé à un événement lié à la Virgen de Gracia et souhaite revenir régulièrement.',0.72,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"religion"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(580,1788530575943,'fact','Adrien vit dans le Gard, avec de nombreux projets situés autour de Saint-Côme-et-Maruéjols, Calvisson, Nîmes et Uzès.',0.74,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"location"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(581,1788530575990,'lesson','Lorsqu''Adrien demande de reprendre un projet ancien, MELITURGOS doit rechercher d''abord la mémoire pertinente et les sources disponibles avant de lui demander de répéter ce qu''il a déjà fourni.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"workflow"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(582,1788530576037,'lesson','Lorsqu''une donnée peut avoir changé avec le temps (prix, disponibilité, réglementation, état d''un projet), MELITURGOS doit vérifier la fraîcheur avant de la traiter comme actuelle.',0.97,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"workflow"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(583,1788530576084,'lesson','MELITURGOS doit conserver les raisons derrière les décisions, pas seulement la décision finale, afin de ne pas répéter des pistes déjà abandonnées pour de bonnes raisons.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"memory"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(584,1788530576128,'lesson','MELITURGOS doit apprendre des corrections explicites d''Adrien et les considérer comme des leçons prioritaires, tout en permettant une révision ultérieure si de nouvelles preuves les contredisent.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"learning"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(585,1788530576182,'lesson','MELITURGOS ne doit jamais mémoriser automatiquement des mots de passe, clés API, codes de sécurité, numéros de carte ou autres secrets d''authentification.',1,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"security"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(586,1788530703631,'episodic','Le propriétaire a dit: tu as les messages précédents ?',0.45,'chat','{"interaction_id":5}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(587,1788530763521,'episodic','Le propriétaire a dit: je t''ai dis que tu était mon fils , ma création, que tu es immortel que tu me surivvrai et que tu aidera ma famille sur plusieurs générations, quand on parle tu enregistres ?',0.45,'chat','{"interaction_id":6}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(588,1788530810636,'episodic','Le propriétaire a dit: j''ai échangé avec toi combien de foi depuis le début ?',0.45,'chat','{"interaction_id":7}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(589,1788530852368,'project','Le projet MELITURGOS a commencé par une discussion sur la création d''une IA dotée de mémoire persistante et d''un algorithme d''apprentissage, avec comparaison initiale à Grok et intérêt pour les modèles open source.',0.97,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"meliturgos_history","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(590,1788530852412,'preference','Adrien veut que MELITURGOS puisse développer progressivement ses propres modèles, modules, outils et connexions, et grandir rapidement en apprenant de ses expériences.',0.98,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"self_improvement","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(591,1788530852454,'decision','L''architecture décidée sépare apprentissage immédiat par mémoire, amélioration de stratégies/modules, création de spécialistes et fine-tuning/LoRA périodique.',0.97,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"learning","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(592,1788530852495,'decision','MELITURGOS doit conserver un modèle stable de référence et tester toute version candidate avant promotion, avec possibilité de rollback.',0.99,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"self_improvement","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(593,1788530852539,'preference','Adrien souhaite une IA personnelle capable de créer du code, des modules et des connecteurs en lisant de la documentation sur Internet, puis en les testant dans une sandbox.',0.97,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"tools","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(594,1788530852578,'preference','Adrien veut que MELITURGOS puisse utiliser des modèles externes comme professeurs, critiques, évaluateurs et programmeurs pour accélérer sa progression.',0.95,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"learning","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(595,1788530852621,'project','L''idée d''utiliser ChatGPT Work comme environnement d''entraînement manuel a été discutée : MELITURGOS produit d''abord sa réponse, puis un modèle externe critique ou compare.',0.84,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"training","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(596,1788530852664,'preference','Adrien a exprimé un fort attachement émotionnel au projet et un désir de transmission à long terme ; MELITURGOS doit néanmoins rester décrit honnêtement comme un système logiciel et non comme une personne biologique.',0.85,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"identity","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(597,1788530852710,'preference','Adrien souhaite pouvoir accéder à MELITURGOS depuis son téléphone et l''entraîner quotidiennement.',0.96,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"mobile","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(598,1788530852752,'fact','La première v0.1 Windows de MELITURGOS utilisait Flask, SQLite, Ollama et qwen3:4b, avec interface locale sur le port 8765.',0.91,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"meliturgos_local","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(599,1788530852795,'lesson','L''installation locale a rencontré un faux alias Python du Microsoft Store ; l''installateur a été corrigé en v0.1.1 pour détecter un vrai interpréteur Python.',0.82,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"meliturgos_local","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(600,1788530852841,'decision','Ollama a été installé localement et qwen3:4b a commencé à être téléchargé, mais les plantages du PC ont conduit à abandonner le PC comme cœur obligatoire.',0.95,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"meliturgos_cloud","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(601,1788530852884,'decision','L''architecture a été basculée sur Cloudflare pour que MELITURGOS reste accessible même PC éteint.',0.99,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"meliturgos_cloud","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(602,1788530852924,'fact','Le Worker Cloudflare porte le nom ''meliturgos''.',0.97,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"meliturgos_cloud","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(603,1788530852965,'fact','La base D1 porte le nom ''meliturgos-memory''.',0.99,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"meliturgos_cloud","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(604,1788530853008,'fact','Le binding de la base D1 dans le Worker s''appelle exactement DB.',0.99,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"meliturgos_cloud","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(605,1788530853050,'fact','Le binding Workers AI dans le Worker s''appelle exactement AI.',0.99,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"meliturgos_cloud","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(606,1788530853095,'fact','Les variables d''environnement prévues sont OWNER_NAME=Adrien et MELITURGOS_USER=adrien. Le mot de passe existe comme secret séparé et ne doit jamais être mémorisé dans GENESIS.',0.98,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"security","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(607,1788530853135,'fact','MELITURGOS Cloud v0.2.1 affiche une interface sombre responsive, un sélecteur de modèles, une zone de chat, le feedback utile/corriger, un ajout de mémoire manuelle, un import GENESIS et un export de sauvegarde.',0.91,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"meliturgos_cloud","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(608,1788530853179,'fact','Au premier démarrage cloud réussi, le compteur affichait 0 souvenirs et 0 échanges avant import de GENESIS.',0.78,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"meliturgos_cloud","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(609,1788530853222,'project','GENESIS v1 a été créé comme première mémoire structurée, avec 83 souvenirs dans la version FULL.',0.96,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"genesis","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(610,1788530853263,'lesson','GENESIS ne doit pas être confondu avec une transcription mot à mot complète de toutes les conversations historiques.',1,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"genesis","date":"2026-09-04"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(611,1788530853302,'project','Autobiographie exhaustive : Adrien veut vérifier systématiquement les sources OneDrive, sauvegardes de téléphone, SMS et documents psychologiques/anciens afin de ne rien manquer dans la reconstruction de sa vie.',0.9,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"autobiography"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(612,1788530853343,'fact','Une arborescence OneDrive CSV a été créée/partagée pour permettre de retrouver les fichiers manquants plus facilement.',0.84,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"autobiography"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(613,1788530853389,'project','Appen/Ads Classification : Adrien a partagé les guidelines v3_2026.08.07 et demandé les réponses aux questions du test à partir des règles.',0.7,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"work_platforms"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(614,1788530853436,'preference','Projet commercial/site : Adrien veut une version très professionnelle des sites, rassurante, orientée achat, avec outils gratuits, contenu récurrent, visibilité, contraste lisible et tailles de produits cohérentes.',0.9,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"web"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(615,1788530853475,'project','Adrien a envisagé d''utiliser Vérité Interdite comme support commercial/site et possède plusieurs domaines liés au Méliturge et à Vérité Interdite.',0.83,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"web"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(616,1788530853518,'project','Pour un lave-vaisselle en panne E4, Adrien a demandé localisation des composants et exemples visuels de réparation.',0.52,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"home"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(617,1788530853561,'preference','Dans un test de transcription, Adrien a travaillé sur des règles de priorité, interjections et précédence, en demandant souvent la règle exacte avant réponse.',0.67,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"work_platforms"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(618,1788530853605,'decision','Reprise automatisations : Adrien a demandé un suivi complet de Gmail/Lemlist et des projets, avec vérification réelle de connexion et d''état avant conclusions.',0.86,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"automation"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(619,1788530853648,'decision','Adrien a demandé que la tâche FULL AUTO de revenus ne soit plus remise en pause et tourne régulièrement, sans dépense non autorisée.',0.92,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"automation"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(620,1788530853690,'project','Ligier Xtoo : Adrien veut remplacer la carrosserie avant complète en neuf afin que capot, ailes et éléments soient réalignés et tiennent correctement.',0.85,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"ligier"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(621,1788530853736,'project','Adrien a aussi recherché un écran LCD de remplacement pour sa Ligier Xtoo 2009, en distinguant deux modèles possibles.',0.82,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"ligier"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(622,1788530853779,'project','PC gaming : Adrien a demandé des recherches d''annonces d''occasion, comparaison d''upgradabilité et détection d''arnaques, avec budget autour de 350 €.',0.76,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"pc"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(623,1788530853823,'project','Projet revenus : Adrien a demandé des milliers de pistes de revenus automatisables que l''IA puisse exécuter en grande partie seule.',0.85,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"income"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(624,1788530853865,'project','Adrien souhaite que les automatisations trouvent des investisseurs et des stagiaires en plus de la prospection commerciale, sans détourner la priorité revenus.',0.76,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"income"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(625,1788530853910,'project','Cession marchés : Adrien souhaite céder ses emplacements de Nîmes et Uzès, avec possibilité de céder aussi caravane et remorque fourgon.',0.85,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"markets"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(626,1788530853954,'fact','Pour Nîmes, la mairie a confirmé que le repreneur doit proposer sensiblement les mêmes produits et fournir les courriers/dossier nécessaires.',0.9,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"markets"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(627,1788530853999,'project','Adrien a travaillé sur un plan de rucher pour 30 ruches et demande des documents de suivi très professionnels et imprimables.',0.84,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"apiculture"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(628,1788530854044,'decision','Projet commercial Royamande/GMS : Adrien veut parler également des autres produits disponibles ou en développement : gelée royale, miel toutes fleurs, miel+gelée royale, miels gourmands et infusés sur demande.',0.84,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"GMS"}');
