INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(655,1788530855358,'decision','La règle opérationnelle définie est qu''un seul bilan global quotidien est envoyé à Adrien, mais cela ne limite pas les emails de prospection envoyés aux tiers.',0.9,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"automation","date":"2026-08-26"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(656,1788530855403,'lesson','La campagne Lemlist ''GMS France - Royamande & gamme Atelier du Méliturge'' a été associée à une alerte de délivrabilité : ne pas monter en charge tant que la boîte n''est pas suffisamment saine.',0.88,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"prospecting","date":"2026-08-26"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(657,1788530855445,'lesson','Le registre de revenus fin août 2026 indiquait que le pack de pilotage apicole et le simulateur B2B étaient SETUP_READY mais qu''aucune vente ne devait être comptée comme revenu avant encaissement réel.',0.9,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"income","date":"2026-08-30"}');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata") VALUES(658,1788530855488,'lesson','GENESIS MAX v2 rassemble les souvenirs structurés disponibles dans le contexte de ChatGPT, les résumés de conversations récentes, la chronologie MELITURGOS et un index de documents retrouvés dans la Library. Il ne constitue pas une exportation mot à mot de l''intégralité des conversations de tout le compte ChatGPT.',1,'import','{"genesis_version":"2.0-max-accessible","source":"accessible_chat_context_and_library_index","sensitivity":"normal","topic":"genesis","date":"2026-09-04"}');
